insert into corpus_findings
  (area, topic, claim, basis, confidence, sport, quantities, source)
values
('volume-per-muscle', 'weekly set volume for hypertrophy', 'Doucette coaches roughly 10 to 20 total working sets per body part per week to maximize hypertrophy: heavier, lower-rep training should land near the top of that range (about 20 sets), while higher-rep, high-effort training taken to failure should land nearer the bottom (about 10 sets).', 'practice', 'weak', NULL, '{"sets_per_muscle_per_week_min": 10, "sets_per_muscle_per_week_max": 20, "note": "lower-rep heavy work trends toward 20 sets; high-rep high-effort work trends toward 10 sets"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Heavy Vs Light Weights || Best For Muscle Growth'),
('progression', 'rep range by training age and drug status', 'Doucette scales working rep range to training experience and PED status: beginners train 12 to 15 reps (technique-focused, weight kept light enough for mind-muscle connection and a controlled tempo), intermediates 8 to 15 reps, natural advanced lifters closer to 15 reps, and PED-enhanced advanced lifters trend toward 15 to 20-plus reps, specifically advised against low-rep heavy sets.', 'practice', 'weak', NULL, '{"beginner_reps": "12-15", "intermediate_reps": "8-15", "advanced_natural_reps": "~15", "advanced_enhanced_reps": "15-20+"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Heavy Vs Light Weights || Best For Muscle Growth'),
('clinical', 'PED strength-tendon mismatch and injury risk', 'Doucette says PED-enhanced lifters carry elevated injury risk from heavy low-rep training because their muscles get stronger faster than their tendons can adapt, so he coaches enhanced lifters toward lighter loads and higher reps specifically to reduce injury risk.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Heavy Vs Light Weights || Best For Muscle Growth'),
('guideline', 'effort capacity differs by rep range', 'Doucette claims it is mentally and physically harder to push a set of 15 to 20 reps to true failure than a set of 5 to 8 reps to failure, so he assigns rep range by how hard a trainee actually pushes themselves: lifters who habitually stop short of failure are coached toward lower reps (around 8) where reaching genuine effort is easier, while the hardest-working trainees are coached toward higher reps (around 15) since they can genuinely reach failure there.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Heavy Vs Light Weights || Best For Muscle Growth'),
('periodization', 'alternating hypertrophy and strength mesocycles', 'Doucette recommends periodizing between an 8 to 12 week higher-rep hypertrophy block and a 4 to 8 week heavier lower-rep strength block, repeating the cycle, or combining both in one session by starting with heavier sets (8 to 10 reps) and finishing with a lighter drop set to 20 to 25 reps; he cites Larry Wheels training near-max heavy for strength and then dropping the load for very high reps as an example of converting new strength into added hypertrophy volume.', 'opinion', 'weak', NULL, '{"hypertrophy_block_weeks": "8-12", "strength_block_weeks": "4-8", "example_drop_set_reps": "20-25"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Heavy Vs Light Weights || Best For Muscle Growth'),
('tempo', 'warm-up tempo used purely to prime the nervous system', 'CBum''s coach has him run warm-up sets with a fixed eccentric-pause-concentric tempo (about a 3-count down, pause in the stretch, fast up) purely to teach the nervous system that the load is getting heavier, explicitly reserving true maximal effort for the working sets rather than pushing the warm-ups hard.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Chest and Triceps Workout'),
('guideline', 'heaviest work first in the session while freshest', 'CBum''s coach front-loads the heaviest, lowest-rep working set at the start of the chest session while the lifter is freshest, reasoning that a fresh nervous system recruits fast-twitch fibers most efficiently and those fibers carry the highest hypertrophy potential; intensity descends toward higher-rep burnout and isolation work later in the session.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Chest and Triceps Workout'),
('tempo', 'speed intent on the concentric even under heavy load', 'CBum is cued to move the concentric with full speed intent even on the heaviest working set, where the bar itself only moves for roughly two seconds, while keeping a controlled eccentric and pausing in the stretched position; the coaching point is that intent to move fast, not actual bar velocity, is what recruits fast-twitch fibers.', 'practice', 'weak', NULL, '{"eccentric_count": "3 down, pause in stretch", "concentric_intent": "maximal speed regardless of actual bar speed"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Chest and Triceps Workout'),
('volume-per-muscle', 'individualizing main-lift rep count by how the athlete responds to volume', 'CBum''s coach individualizes the rep count on the primary working set by how that specific athlete responds to volume: an athlete who responds well to less volume is kept on lower reps for the main lift, with volume added later via other sets or accessory work rather than by adding reps to the main lift.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Chest and Triceps Workout'),
('strength-accessories', 'technical failure, not just rep-max failure', 'CBum''s coach defines the target on isolation/machine work as technical failure, meaning failure of the specific targeted muscle fiber pattern while holding exact range of motion and tempo, rather than sacrificing form to squeeze out additional reps.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Chest and Triceps Workout'),
('strength-accessories', 'not returning to heavy compound loading once a muscle is neurally exhausted', 'Once compound pressing work has fully fatigued a muscle to the point the coach says the body is done recruiting for that pattern, CBum''s session does not return to heavy compound loading; it moves instead to movements the body can still recruit, such as isolation or cable work.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Chest and Triceps Workout'),
('strength-accessories', 'picking an exercise variation by individual feel', 'CBum''s coach lets exercise-variation choice for isolation work be guided by which pattern the specific athlete feels the target muscle in best, for example choosing the cross-body cable triceps variant for a training partner specifically because that partner reported activating his triceps well across all cable angles, rather than defaulting to one best variation for everyone.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Chest and Triceps Workout'),
('strength-accessories', 'training full range of motion, even unloaded, for development and posing', 'CBum argues that if you cannot achieve a full range of motion in training, even with no load, you will not recruit those fibers, and the muscle will not develop or present the same when posing on stage; he treats full range of motion practice, even unloaded, as necessary for both muscular development and injury prevention.', 'opinion', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Chest and Triceps Workout'),
('tempo', 'continuous tension, no resting points within a rep', 'CBum''s coach cues no resting points in the movement on machine press work, meaning continuous tension throughout the rep rather than locking out or pausing to rest at the top.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Chest and Triceps Workout'),
('volume-per-muscle', 'choosing training frequency by weekly volume load', 'Humiston''s practical rule for picking a split: if total weekly volume for a muscle exceeds about 20 sets, split it across more sessions or days; if it is under that, training a muscle once per week is fine, though he treats roughly twice per week as his general optimal recommendation for natural lifters as long as recovery is managed.', 'opinion', 'weak', NULL, '{"sets_threshold_for_splitting": 20, "recommended_frequency": "~2x/week (natural)", "frequency_range": "1-3x/week"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — THIS Builds The MOST Muscle (Science-Backed Blueprint For Adding MASS!)'),
('volume-per-muscle', 'starting point for weekly set volume', 'Humiston recommends starting at 10 working sets per muscle per week and increasing incrementally if progress stalls, holding volume steady on muscles that already respond well and adding volume specifically to lagging muscle groups.', 'opinion', 'weak', NULL, '{"starting_sets_per_muscle_per_week": 10, "note": "increase progressively on non-responsive muscles only"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — THIS Builds The MOST Muscle (Science-Backed Blueprint For Adding MASS!)'),
('volume-per-muscle', 'rest-pause and drop sets counted as roughly three sets', 'Humiston treats a rest-pause or drop set as roughly equivalent to three traditional sets for volume-counting purposes, so swapping one straight set for a rest-pause or drop set is a way to add volume without adding a full extra set.', 'opinion', 'weak', NULL, '{"rest_pause_or_drop_set_equivalent_sets": 3}'::jsonb, 'Ryan Humiston (physique, exercise selection) — THIS Builds The MOST Muscle (Science-Backed Blueprint For Adding MASS!)'),
('guideline', 'training closer to failure than RIR targets due to self-assessment error', 'Despite citing research showing no statistical hypertrophy difference training to failure versus leaving up to 3 reps in reserve, Humiston personally trains closer to failure because he believes most lifters, himself included, underestimate reps left in the tank by about 2, so a 3-RIR target often becomes a 5-RIR effort in practice; he would rather train hard and take an extra rest day than deliberately leave reps in the tank.', 'opinion', 'weak', NULL, '{"common_rir_target": 3, "typical_rir_estimation_error_reps": 2}'::jsonb, 'Ryan Humiston (physique, exercise selection) — THIS Builds The MOST Muscle (Science-Backed Blueprint For Adding MASS!)'),
('tempo', 'experimenting with a slow eccentric, fast concentric tempo', 'Humiston started personally testing a 3-second eccentric with a 1-second explosive concentric tempo, while flagging that the meta-analysis that prompted it drew on questionable subject pools for each half of the claim.', 'practice', 'weak', NULL, '{"eccentric_seconds": 3, "concentric_seconds": 1}'::jsonb, 'Ryan Humiston (physique, exercise selection) — THIS Builds The MOST Muscle (Science-Backed Blueprint For Adding MASS!)'),
('volume-per-muscle', 'his own split structure', 'Humiston''s personal upper-lower split trains each muscle twice per week as a baseline, but bumps to three times in the workout every third week.', 'practice', 'weak', NULL, '{"base_frequency_per_week": 2, "periodic_bump_frequency_per_week": 3, "bump_cadence": "every 3rd week"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — THIS Builds The MOST Muscle (Science-Backed Blueprint For Adding MASS!)'),
('smith', 'Smith machine for pushing sets closer to true failure', 'Tennyson uses the Smith machine over free-weight bench press specifically because the fixed bar path lets him safely push a set past the point he could self-spot on a free bench, getting extra close-to-failure reps he says he would not get on the barbell.', 'practice', 'weak', NULL, '{"note": "example given: several additional high-quality reps near failure versus free bench"}'::jsonb, 'Will Tennyson (experiments, self-testing) — How I Blew Up My Chest'),
('strength-accessories', 'avoiding pre-exhaustion before the main compound press', 'Tennyson avoids pre-exhausting the chest with an isolation fly before the main compound press for most lifters, because starting fatigued reduces the load used on the bench and, in his framing, shifts more of the lockout work to the triceps and less to the chest; he reserves pre-exhaust ordering for very advanced, very strong lifters where the compound lift itself is too taxing on joints and recovery to always do first.', 'opinion', 'weak', NULL, '{"reversed_order": "flies performed after bench, not before", "pre_exhaust_exception_threshold": "roughly 405 lb bench for multiple reps"}'::jsonb, 'Will Tennyson (experiments, self-testing) — How I Blew Up My Chest'),
('tempo', 'partial reps past failure in the stretch position', 'Tennyson extends select chest sets past full-rep failure with partial reps performed in the bottom, stretched portion of the range, which he believes is where most chest growth occurs, continuing until even partial reps are not possible; he limits this to a couple of exercises and the last one or two sets of a session because of how taxing it is.', 'practice', 'weak', NULL, '{"scope": "1-2 sets, on a couple of exercises per session"}'::jsonb, 'Will Tennyson (experiments, self-testing) — How I Blew Up My Chest'),
('equipment', 'chest press machine setup for a deeper stretch', 'Tennyson prefers chest press machines for isolating rep quality without stabilizer demand, and sets the handles back as far as possible with a start position around nipple height or slightly higher to get a deeper stretch and press angle.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — How I Blew Up My Chest'),
('tempo', 'pausing every rep in the stretch position, at a reduced weight', 'Tennyson pauses every rep at the stretched, bottom position on chest presses, deliberately using a lighter weight than he otherwise could, because he believes the stretch position is where most chest growth occurs; he checks himself with a visible mark on the sternum as confirmation the pause was actually held.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — How I Blew Up My Chest'),
('tempo', 'going past normal range of motion on chest press', 'Tennyson deliberately goes below a standard bottom position on chest press, using a cambered bar when available or consciously lowering a dumbbell past where most lifters stop, reporting it requires dramatically less weight than his normal working weight but produces a much stronger training effect; he frames this as needing good technique rather than heavy weight.', 'practice', 'weak', NULL, '{"extended_rom_dumbbell_weight_kg": 30, "normal_working_dumbbell_weight_lb": 140, "normal_working_reps": 8}'::jsonb, 'Will Tennyson (experiments, self-testing) — How I Blew Up My Chest'),
('strength-accessories', 'cue to reach the chest toward the ceiling during the descent', 'Tennyson cues himself to actively reach the chest toward the ceiling as the bar descends on presses, which he says helped him feel his chest during incline pressing after previously struggling to connect with it.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — How I Blew Up My Chest'),
('strength-accessories', 'training triceps directly after chest to address lockout weakness', 'Tennyson trains triceps directly after chest because he believes bench lockout weakness is usually a triceps limitation rather than a chest one; his go-to pairing is straight-bar pushdowns followed by overhead extensions, favoring overhead extension variations because he believes they best target the long head of the triceps.', 'practice', 'weak', NULL, '{"pushdown_sets": 3, "pushdown_reps": "10-12", "overhead_extension_sets": 3, "overhead_extension_reps": "12-15"}'::jsonb, 'Will Tennyson (experiments, self-testing) — How I Blew Up My Chest'),
('periodization', 'splitting chest volume across two dedicated days rather than one', 'Tennyson splits chest into two dedicated sessions per week rather than one high-volume day, structuring day one as incline press, then flat press, then 2 to 3 sets of flies, and day two as flat press, then incline press, then 2 to 3 sets of flies or dips, explicitly against doing a single day with around 25 chest sets.', 'practice', 'weak', NULL, '{"sessions_per_week": 2, "flies_sets_per_session": "2-3"}'::jsonb, 'Will Tennyson (experiments, self-testing) — How I Blew Up My Chest'),
('strength-accessories', 'near-straight-arm standing pullover to keep tension in the lat, not the traps', 'Humiston performs standing pullovers with the arm almost straight, only a slight bend, rather than leaning heavily forward, reasoning from scapulohumeral rhythm that leaning forward shifts responsibility to the traps once the arm passes a certain raise angle; his cue is to depress the scapula, engage serratus anterior, and finish the flexion with the lat so tension stays in the lat rather than the upper traps.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get a WIDER BACK!'),
('tempo', 'partial reps past failure in the lengthened position', 'Like Will Tennyson describes for chest, Humiston continues sets, in his case standing pullovers, past full-range failure with 3 to 4 additional partial reps in the lengthened position, treating those final partials as more important to growth than the full-range reps that preceded them.', 'practice', 'moderate', NULL, '{"example_full_reps": 19, "additional_partial_reps": "3-4", "note": "confidence raised to moderate: same specific practice (partials past failure in the stretch) independently described by a different channel, Will Tennyson, in this batch"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — How To Get a WIDER BACK!'),
('guideline', 'contradiction: training to complete failure versus reps-in-reserve research', 'Humiston insists a set does not count for him unless it is taken to complete failure with zero reps left in reserve, and is openly skeptical of reps-in-reserve research, saying that even well-known exercise scientists'' version of failure did not look like true failure when he watched them train. This directly conflicts with the reps-in-reserve literature the corpus holds at higher confidence, which finds RIR-based training within a few reps of failure produces comparable hypertrophy to training to complete failure; his position is that most people, including study subjects, are not accurately assessing how close to failure they really are.', 'opinion', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get a WIDER BACK!'),
('strength-accessories', 'landmine row emphasizing the stretch over the contraction', 'On the one-arm landmine row, Humiston''s focus is loading the lat at length during the eccentric, treating the concentric contraction as almost an afterthought, despite the exercise having a short overall range of motion; his framing is that most of the growth stimulus happens in the stretch, not the squeeze.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get a WIDER BACK!'),
('strength-accessories', 'wide grip on lat pulldown to reduce bicep involvement', 'Humiston uses a wide bar grip on lat pulldown specifically because a wider hand position reduces bicep involvement, letting him focus entirely on scapular control; his technique fault to avoid is letting the scapula elevate or shrug, which shifts the work into the traps instead of the lat.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get a WIDER BACK!'),
('strength-accessories', 'unilateral dumbbell work to diagnose and manage side-to-side asymmetry', 'Humiston prefers dumbbells and single-arm variations over barbells for back exercises partly to identify and manage side-to-side asymmetry, noting that on barbell rows one elbow commonly kicks out more than the other due to a shoulder limitation on that side, preventing full lat engagement on that side specifically.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get a WIDER BACK!'),
('strength-accessories', 'four staple categories for a back workout', 'Humiston says he always includes four categories of movement in a back workout: a lat pulldown variant, a pullover movement, an exercise that loads the lat in a stretched position such as a single-arm landmine or iso row, and a high-elbow row targeting rhomboids and mid-traps, which he says most lifters neglect in favor of heavy rows and spinal-erector work.', 'practice', 'weak', NULL, '{"staple_categories": ["lat pulldown variant", "pullover movement", "stretch-position lat exercise (e.g. single-arm landmine row)", "high-elbow row for rhomboids/mid-traps"]}'::jsonb, 'Ryan Humiston (physique, exercise selection) — How To Get a WIDER BACK!'),
('volume-per-muscle', 'drop sets and rest-pause as time-savers, not extra hypertrophy', 'Humiston states plainly that research does not show drop sets or rest-pause sets produce more hypertrophy than straight sets, only that they collapse the time needed to do the same amount of work; he uses them on his last two or three sets of an exercise for time efficiency, not because he believes they are superior for growth.', 'opinion', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get a WIDER BACK!'),
('strength-accessories', 'hip hinge mobility as a prerequisite for loading a stretch-position back exercise', 'Humiston notes that lifters who lack hamstring flexibility and hip mobility commonly cannot hinge at the hips with a straight back on stretch-position back exercises like straight-leg deadlifts or bent-over rows, and end up rounding the lower back instead; without adequate hip hinge mobility, he says the exercise cannot be loaded correctly.', 'opinion', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get a WIDER BACK!'),
('strength-accessories', 'setting up an exercise for a specific target muscle rather than a general body part', 'Humiston argues that vague exercise-to-goal thinking, such as squatting to train legs in general, limits growth, and that lifters should decide the specific muscle target for a given variation before setting up, for example high-bar squat with feet close for quads versus low-bar squat with feet wide and a limited range of motion for glutes.', 'opinion', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How to Get More Muscular GLUTES! Psst.. You''re Doing These Wrong'),
('strength-accessories', 'glute-biased sumo deadlift setup', 'For a glute-focused sumo deadlift, Humiston sets up with feet only slightly wider than shoulder width rather than maximally wide, toes turned out 45 to 60 degrees, uses lifting straps regardless of load so grip is never the limiter, and lifts without shoes for a stable base.', 'practice', 'weak', NULL, '{"stance_width": "slightly wider than shoulder width", "foot_angle_degrees": "45-60", "equipment": ["straps", "no shoes"]}'::jsonb, 'Ryan Humiston (physique, exercise selection) — How to Get More Muscular GLUTES! Psst.. You''re Doing These Wrong'),
('strength-accessories', 'limiting knee extension to bias a deadlift toward the glutes', 'Humiston''s key technique cue for a glute-biased sumo deadlift is to intentionally limit knee extension throughout the rep, analogous to fixing the elbow position on a lat pulldown to reduce bicep involvement, so the quads cannot take over; he redefines the top of the rep as full hip and glute flexion with a slight hip rotation rather than a locked-out knee, cueing lifters to keep the same knee bend and rotate over the top of the hips.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How to Get More Muscular GLUTES! Psst.. You''re Doing These Wrong'),
('progression', 'resetting each rep from the floor while learning an unfamiliar bar path', 'Because the limited-knee-extension sumo pull feels unfamiliar, Humiston has lifters reset from the floor after every single rep at first, rather than doing touch-and-go reps, so they can recheck foot and knee position, back engagement, and hip shift before each pull.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How to Get More Muscular GLUTES! Psst.. You''re Doing These Wrong'),
('volume-per-muscle', 'mixing very low and very high rep ranges on the same variation', 'Humiston programs this glute-biased sumo pull across both heavy low-rep sets and very high-rep sets up to around 30 reps, arguing both ranges are worthwhile once the movement is properly isolating the glutes rather than the quads.', 'opinion', 'weak', NULL, '{"high_rep_example": 30}'::jsonb, 'Ryan Humiston (physique, exercise selection) — How to Get More Muscular GLUTES! Psst.. You''re Doing These Wrong'),
('strength-accessories', 'training rear and side delts before front-delt-dominant pressing', 'Tennyson trains rear and side delts before front-delt-dominant overhead pressing, arguing that pre-fatiguing the rear and side delts makes them the limiting factor once pressing begins, producing a more even stimulus across all three deltoid heads at the cost of needing a lighter press weight.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — How I Grew Wide Shoulders FAST!'),
('tempo', 'stopping short of lockout on cable face pulls to keep constant tension', 'On cable face pulls, Tennyson stops just short of full lockout at the top to keep constant tension on the rear delts rather than resting there, and controls the descent slowly, working around 3 sets of roughly 25 reps.', 'practice', 'weak', NULL, '{"sets": 3, "reps": "~25"}'::jsonb, 'Will Tennyson (experiments, self-testing) — How I Grew Wide Shoulders FAST!'),
('strength-accessories', 'choosing an exercise variation by mind-muscle connection over hardware similarity', 'Tennyson prefers the single-arm cable rear-delt fly over the reverse pec-deck machine specifically because he says he cannot connect with his rear delts as well on the pec-deck version, illustrating that his exercise choice is driven by which variation he personally feels the target muscle working in.', 'opinion', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — How I Grew Wide Shoulders FAST!'),
('strength-accessories', 'treating the top portion of a lateral raise as low-value junk volume', 'Tennyson treats the top portion of a standing dumbbell lateral raise, from horizontal up toward shoulder height, as comparatively low-value because the delt is resting there, so he starts a 45-degree lateral raise from a partial position that keeps tension on through the working range, then continues directly into upright rows once that lateral raise reaches failure as a mechanical drop set.', 'opinion', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — How I Grew Wide Shoulders FAST!'),
('strength-accessories', 'myo-rep match sets for delts', 'Tennyson uses myo-rep match sets for delts, a technique he credits to Dr. Mike Israetel: a first straight set is taken to absolute failure to set a rep target, for example 20 reps, and two more mini-sets are performed by resting only about 5 seconds after reaching failure and continuing until the same rep target is matched, repeated for a total of three rounds.', 'practice', 'weak', NULL, '{"rest_between_mini_sets_seconds": 5, "total_rounds": 3, "example_target_reps": 20}'::jsonb, 'Will Tennyson (experiments, self-testing) — How I Grew Wide Shoulders FAST!'),
('tempo', 'partial reps past full range of motion until literal failure', 'As with his chest training, Tennyson continues lateral-raise sets past the point of full range of motion with partial reps until literal failure rather than stopping once he cannot complete a full rep, grouping this with drop sets, supersets, and cheat reps as ways to extend a set to true failure.', 'practice', 'moderate', NULL, '{"note": "confidence raised to moderate: this practitioner independently describes the same partials-past-failure pattern on two different exercises in this batch, and Ryan Humiston independently describes the same practice on pullovers"}'::jsonb, 'Will Tennyson (experiments, self-testing) — How I Grew Wide Shoulders FAST!'),
('tempo', 'prioritizing tempo and range of motion over load on overhead press', 'Tennyson explicitly prioritizes controlled tempo and full range of motion over load on overhead pressing, saying he would rather do 10 clean reps than 15 mediocre ones, and sets dumbbell width so the outside of the dumbbell lines up with the outside of the shoulder to maximize stretch at the bottom, even when that means a much lighter working weight.', 'opinion', 'weak', NULL, '{"example_working_weight_lb": 50, "example_reps_to_failure": 10}'::jsonb, 'Will Tennyson (experiments, self-testing) — How I Grew Wide Shoulders FAST!'),
('equipment', 'seated versus standing overhead press by goal', 'Tennyson recommends a seated overhead press over a standing one when the specific goal is maximum delt hypertrophy, citing more time under tension, more focus on the delt, and lower injury risk, reserving the standing press for when general athleticism and strength carryover are also goals.', 'opinion', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — How I Grew Wide Shoulders FAST!'),
('volume-per-muscle', 'very high accumulated lateral raise volume', 'Tennyson reports doing around 100 total lateral raise reps after every workout as an accumulated-volume approach, arguing delts specifically can tolerate very high total volume and that repeated high-rep exposure improves movement efficiency over time, eventually allowing heavier loading.', 'practice', 'weak', NULL, '{"daily_lateral_raise_reps": 100, "frequency": "after every workout"}'::jsonb, 'Will Tennyson (experiments, self-testing) — How I Grew Wide Shoulders FAST!'),
('clinical', 'loaded end-range isometric holds to correct chronically rounded shoulders', 'Humiston''s fix for rounded-shoulder posture that has not responded to passive stretching plus posterior-chain strengthening is a loaded isometric hold in the fully lengthened position of chest movements such as flies, presses, or dip machine reps, reasoning that chronic shortened-range training has shortened the muscle fibers, and holding a comfortable, not maximal, end-range position under light load will lengthen them back out over time.', 'practice', 'weak', NULL, '{"example_fly_load_lb": 15, "example_press_load_lb": 40, "example_dip_load": "bodyweight", "exercises": ["flies", "presses", "dip machine"]}'::jsonb, 'Ryan Humiston (physique, exercise selection) — How To Fix Rounded Shoulders (THIS ACTUALLY WORKS!)'),
('strength-accessories', 'full-range-of-motion sets to rebuild lost range before or after working sets', 'For a lifter whose range of motion or posture has degraded, Humiston has them perform full-stretch-to-full-contraction reps specifically as warm-up sets, before switching to whatever range they can actually connect with for the working sets, or alternatively adds 1 to 2 full-range sets onto the end of every exercise, arguing that training exclusively in a partial, comfortable range reinforces the postural problem.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Fix Rounded Shoulders (THIS ACTUALLY WORKS!)'),
('equipment', 'foam roller under the upper back to assist reaching a stretched shoulder position', 'Humiston has lifters place a foam roller under their upper back during chest flies or presses if they cannot otherwise reach a proper stretched shoulder position, to mechanically assist getting into the target posture.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Fix Rounded Shoulders (THIS ACTUALLY WORKS!)'),
('strength-accessories', 'three-part criteria for what makes a best exercise', 'Nippard selects a best exercise for a muscle using three criteria: high tension at a high stretch, meaning the muscle has real resistance to work against in the lengthened position; a clean feel, meaning it is felt in the target muscle rather than in a joint; and potential for overload, meaning the ability to add reps or load over time.', 'opinion', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — The Best Exercises For Every Muscle ft. Jeff Nippard'),
('strength-accessories', 'long-length partial reps on squat to bias the stretched position', 'Nippard and Tennyson describe long-length partials on squat, doing partial reps confined to the bottom, stretched half of the range and returning down without going higher than about halfway up, as a harder, no-rest-at-the-top variant they use to bias stimulus toward the stretched position of the quads.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — The Best Exercises For Every Muscle ft. Jeff Nippard'),
('strength-accessories', 'seated over lying leg curl for a pre-stretched hamstring', 'Nippard prefers the seated hamstring curl over the lying leg curl because the seated position pre-stretches the hamstring at the start of the rep, whereas lying leaves it unstretched at the start; he cites a 12-week comparison he references informally showing roughly 1.5 times more hamstring growth with seated versus lying curls, with the one hamstring head that does not cross the hip joint showing no difference between the two variations, which he reads as evidence for a stretch-mediated effect.', 'opinion', 'weak', NULL, '{"relative_growth_seated_vs_lying": "~1.5x", "study_duration_weeks": 12}'::jsonb, 'Will Tennyson (experiments, self-testing) — The Best Exercises For Every Muscle ft. Jeff Nippard'),
('strength-accessories', 'leaning further forward on an RDL to increase hamstring stretch', 'Nippard notes a standard RDL does not stretch the short head of the biceps femoris, since it does not cross the hip joint and can only be trained through knee-flexion movements like leg curls, and separately cues leaning further forward on an RDL to increase hamstring stretch as long as the position still feels stable and can still be loaded progressively.', 'opinion', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — The Best Exercises For Every Muscle ft. Jeff Nippard'),
('strength-accessories', 'pushing high-rep sets past the point that feels like failure', 'Nippard notes that on high-rep cable work people commonly stop at a point that feels like failure, for example 15 reps, but can typically push 4 to 5 more reps if they actually continue to true failure, and separately says roughly 3 sets a week for a muscle is enough to produce about 60 percent of that muscle''s maximum achievable growth for most people.', 'opinion', 'weak', NULL, '{"sets_per_week": 3, "pct_of_max_growth": 60, "typical_extra_reps_available_past_perceived_failure": "4-5"}'::jsonb, 'Will Tennyson (experiments, self-testing) — The Best Exercises For Every Muscle ft. Jeff Nippard'),
('strength-accessories', 'back needs one vertical pull and one horizontal pull, and a stability preference for rows', 'Nippard treats back training as needing two distinct pulling patterns in a session, one vertical pull such as a pulldown or pull-up and one horizontal pull such as any row, and prefers a chest-supported row specifically because full-body stability lets him direct all tension into the back instead of spending effort stabilizing.', 'opinion', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — The Best Exercises For Every Muscle ft. Jeff Nippard'),
('progression', 'pulldown preferred over pull-up for consistent progressive overload', 'Nippard prefers lat pulldowns over pull-ups for back training because he finds it easier to progress pulldowns consistently, since bodyweight pull-ups require re-weighing the body each time to accurately gauge added load, making overload harder to track.', 'opinion', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — The Best Exercises For Every Muscle ft. Jeff Nippard'),
('strength-accessories', 'elbow path, not just grip, changes lat versus mid-trap emphasis on pulldown', 'Nippard changes lat pulldown emphasis primarily by elbow path rather than grip width alone: driving the elbows straight down toward the pockets biases the lats, while leaning back and driving the elbows further behind the body biases the mid-traps and rear delts instead, using the same basic pulldown movement with a different joint path.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — The Best Exercises For Every Muscle ft. Jeff Nippard'),
('tempo', 'broad rep-duration window for hypertrophy rather than a fixed tempo', 'Nippard says research he was involved in found that reps totaling roughly 2 to 8 seconds of combined concentric and eccentric time produced equal hypertrophy, while very fast, bouncy reps and extremely slow reps of 10 to 20-plus seconds were both suboptimal, so his practical standard is a controlled eccentric within that broad window rather than a specific fixed tempo.', 'opinion', 'weak', NULL, '{"optimal_rep_duration_seconds_min": 2, "optimal_rep_duration_seconds_max": 8}'::jsonb, 'Will Tennyson (experiments, self-testing) — The Best Exercises For Every Muscle ft. Jeff Nippard'),
('strength-accessories', 'raising cable height so peak resistance lands in the stretched position', 'Nippard sets cable height on lateral raises, rear-delt flys, and biceps curls so the cable-to-limb angle passes 90 degrees well into the stretched range rather than in the middle of the movement, reasoning that a cable applies its peak resistance at a 90-degree angle to the working limb, so positioning that point toward the end of the stretch shifts more of the exercise''s resistance into the lengthened position.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — The Best Exercises For Every Muscle ft. Jeff Nippard'),
('strength-accessories', 'overhead arm position and a torso-lean kickback to bias the triceps long head', 'Nippard trains the triceps long head, the only head crossing both the shoulder and elbow joints, with overhead arm-position movements to bias its stretch, and modifies the standard kickback by leaning the torso forward so the arm can travel further behind the body, which he describes as biomechanically the stretch-position equivalent of the overhead variation.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — The Best Exercises For Every Muscle ft. Jeff Nippard'),
('periodization', '8-day, 3-on-1-off microcycle built for extra recovery', 'Bumstead''s coach built an 8-day training split, 3 training days followed by 1 rest day, repeating, for this Olympia prep specifically to add more recovery than a standard 6-on-1-off week, citing an autoimmune condition that responds poorly to accumulated stress; he says it was the best-feeling prep he has had and the one in which he retained the most strength through a full contest prep.', 'practice', 'weak', NULL, '{"cycle_length_days": 8, "training_days_per_cycle": 3, "rest_days_per_cycle": 2}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — SHREDDED CHEST WORKOUT | MY OLYMPIA TRAINING SPLIT EXPLAINED'),
('volume-per-muscle', 'very low per-exercise set count offset by drop-set intensity', 'For most of this prep, Bumstead used just two hard working sets per exercise, even on compound lifts, one all-out set followed by one intensifier set such as a drop set, cluster set, or superset, reserving up to three working sets only for isolation finishers like triceps extensions or flies; per-exercise set count was kept low while reps within a set were pushed high, with drop sets going down to around 20 to 25 reps.', 'practice', 'weak', NULL, '{"working_sets_compound": 2, "working_sets_isolation_max": 3, "drop_set_rep_target": "20-25"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — SHREDDED CHEST WORKOUT | MY OLYMPIA TRAINING SPLIT EXPLAINED'),
('strength-accessories', 'splitting back training into a thickness day and a separate width day', 'Bumstead''s split trains back on two separate days, each targeting a different vector: a back thickness day built entirely around rows, such as chest-supported dumbbell rows and machine rows, with no pulldown or pullover work at all, and a separate back width day later in the week built around pulldowns and pullovers targeting the lats specifically; rows are treated as what develops thickness and pulldowns and pullovers as what develops width, each trained in its own dedicated session.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — SHREDDED CHEST WORKOUT | MY OLYMPIA TRAINING SPLIT EXPLAINED'),
('clinical', 'machine-first warm-up sequencing around an old hamstring tear', 'Because of a lingering hamstring tear from the previous year, Bumstead always warms up his heavy hamstring day, built around straight-leg deadlifts, on machines first before progressing to the loaded free-weight movement, rather than warming up directly with the free-weight lift itself.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — SHREDDED CHEST WORKOUT | MY OLYMPIA TRAINING SPLIT EXPLAINED'),
('clinical', 'reducing range of motion and pushing-past-failure work, not load, to protect an injured shoulder pre-competition', 'With a shoulder problem in the final two weeks before competing, Bumstead deliberately switched chest day to Smith machine and other machine presses instead of his normal full-range free-weight bench where he would normally touch his chest, and stopped pushing sets far past failure, while keeping the load itself heavy, still hitting a new heaviest incline press weight; he traded range of motion and extra intensity techniques for joint safety rather than reducing the weight on the bar.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — SHREDDED CHEST WORKOUT | MY OLYMPIA TRAINING SPLIT EXPLAINED'),
('strength-accessories', 'pairing one primary body part with a small amount of a secondary one each session', 'Bumstead structures nearly every session in this split as one primary body part plus a small amount of a secondary one at the end, for example chest day ends with 1 to 2 triceps isolation moves and shoulder day ends with an isolation upper-chest exercise and a fly, usually pec deck, rather than training two full body parts in one session.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — SHREDDED CHEST WORKOUT | MY OLYMPIA TRAINING SPLIT EXPLAINED'),
('strength-accessories', 'pec-deck fly path and lower-chest bias', 'Sam Sulek says running a pec-deck or cable fly with a low finishing path (“lower chest bias”) is close to pointless — he says it just shifts work toward the lower chest, which he claims he has never actually seen as a genuinely lacking area on a physique. He keeps his own pressing work incline-only and treats flat or decline chest work as unnecessary for him.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Spring Bulk Day 132 - Chest, Shoulders, Calves'),
('tempo', 'partial reps into deepest stretch after full-ROM failure', 'On pec-deck/cable fly sets, once Sam Sulek can no longer bring his hands together through the full range, he keeps going with partial reps bouncing into the deepest stretch position (“the hole”) rather than stopping, believing this extends useful stimulus past what stopping at full ROM would give and produces a better pump and, in his view, better gains.', 'practice', 'weak', NULL, '{"note": "extra partial reps performed at end-range stretch after full-ROM failure is reached"}'::jsonb, 'Sam Sulek (high-volume physique training) — Spring Bulk Day 132 - Chest, Shoulders, Calves'),
('volume', 'sets per muscle per session', 'Sam Sulek targets roughly 8 to 12 hard working sets per muscle group per session (11 sets of chest, about 8 rear-delt and 8 side-delt sets in this workout), explicitly calling the number a personal habit rather than “a proven number.” He stops a muscle group once he judges it fully pumped, saying he sees no benefit to continuing once that point is reached.', 'practice', 'weak', NULL, '{"sets_per_muscle_low": 8, "sets_per_muscle_high": 12, "session_example_chest_sets": 11}'::jsonb, 'Sam Sulek (high-volume physique training) — Spring Bulk Day 132 - Chest, Shoulders, Calves'),
('volume-per-muscle', 'training frequency for a lagging body part', 'Sam Sulek recommends the average advanced lifter hit each muscle about twice per week, and suggests deliberately shifting a split to give a weak body part more frequency and volume at the expense of a strong one (e.g., training a lagging chest every 3 days while dropping back to structural work elsewhere).', 'opinion', 'weak', NULL, '{"sessions_per_muscle_per_week": 2}'::jsonb, 'Sam Sulek (high-volume physique training) — Spring Bulk Day 132 - Chest, Shoulders, Calves'),
('progression', 'dropping feeler/ramp sets as training age increases', 'Sam Sulek says he no longer runs light “feeler” ramp-up sets when moving between exercises for the same muscle within a session (e.g., dumbbell curls straight into cable curls) because an experienced lifter already has a good gauge of their working weight; he reserves ramp-up sets for beginners or for genuinely unfamiliar equipment. He contrasts this with his own beginner-era approach of pyramiding up through 5 sets on every exercise, which he has since dropped in favor of starting near his heaviest weight per exercise and letting the load taper down across the session as fatigue accumulates.', 'practice', 'weak', NULL, '{"note": "beginner era: pyramided up across 5 sets per exercise; current: starts near-max load per exercise, weight tapers down set to set as fatigue builds"}'::jsonb, 'Sam Sulek (high-volume physique training) — Spring Bulk Day 132 - Chest, Shoulders, Calves'),
('strength-accessories', 'rear-delt cable cue and single-arm preference', 'On rear-delt cable work Sam Sulek cues himself to rotate the shoulder rather than row it backward, saying moving the shoulder back turns the exercise into trap/lat work instead of isolating the rear delt. He prefers single-arm rear-delt cable work over the double-arm version because double-arm uses enough weight that it becomes hard to balance and control in the air.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Spring Bulk Day 132 - Chest, Shoulders, Calves'),
('volume-per-muscle', 'skipping direct front-delt work', 'Sam Sulek says he has not trained front delts directly in years, reasoning that heavy incline pressing already overloads the front delt enough that dedicated front-delt work is redundant for him.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Spring Bulk Day 132 - Chest, Shoulders, Calves'),
('smith', 'contradiction: behind-the-neck Smith machine press', 'Sam Sulek says behind-the-neck Smith machine press used to be his favorite front-delt/shoulder movement, and that although the exercise “gets a lot of hate,” he doesn''t see much of a problem with it for a lifter who is reasonably flexible. This conflicts with mainstream shoulder-safety guidance, which generally treats loaded behind-the-neck pressing as a high-risk pattern for shoulder impingement and advises against it for most lifters.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Spring Bulk Day 132 - Chest, Shoulders, Calves'),
('guideline', 'judging when an isolation set is done', 'Sam Sulek says he trains compound lifts to literal failure, but for lighter isolation work (dumbbell side raises, pec deck) true mechanical failure becomes “kind of fake” once partial reps are possible, so he instead ends the set once he genuinely believes he went hard — using self-honesty about effort as his practical stopping standard rather than a strict rep target.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Spring Bulk Day 132 - Chest, Shoulders, Calves'),
('tempo', 'shift to extreme stretch-focused range of motion', 'Chris Bumstead describes a coaching-driven change (with Justin King) toward much deeper range of motion on pressing and pulling movements: using a neutral grip, lowering to a full stretch, performing a quarter rep back down into that stretch, then a full rep up. The stated rationale (relayed from his coach) is that training a muscle through a longer stretched position builds it more evenly across its range, makes it stronger and less injury-prone through full ROM, and grows it bigger, versus training that only locks in growth in a shortened position. He reports the style is dramatically more fatiguing than the same load trained with a shorter range.', 'practice', 'weak', NULL, '{"note": "quarter rep performed at deepest stretch, followed by a full rep back up; weight reduced substantially to accommodate the larger range of motion"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Chest Workout Breakdown'),
('strength-accessories', 'load and grip reduction to fix shoulder pain and increase ROM', 'To adopt the deeper-range style, Bumstead switched an incline press from 150 lb with an overhand grip (which was aggravating his shoulder) down to 100 lb with a neutral grip and a much larger range of motion, reporting it feels more effective on his pec while being noticeably easier on the shoulder.', 'practice', 'weak', NULL, '{"weight_before_lb": 150, "weight_after_lb": 100, "grip_before": "overhand", "grip_after": "neutral"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Chest Workout Breakdown'),
('tempo', 'peak-contraction hold on isolation work', 'On isolation movements (pullover, pec deck) within a chest-and-back superset, Bumstead holds the fully contracted/squeezed position for about 15 seconds before performing roughly 10 to 12 reps, deliberately prioritizing time under tension and blood flow in the shortened position over simply moving through reps.', 'practice', 'weak', NULL, '{"squeeze_hold_seconds": 15, "reps_target_low": 10, "reps_target_high": 12, "sets_per_movement": 4}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Chest Workout Breakdown'),
('equipment', 'unilateral-adjustable machine for a chronic shoulder issue', 'Bumstead credits a convertible unilateral/bilateral incline press machine (independent per-arm loading) for helping him manage a chronically unstable shoulder (multiple prior labrum surgeries) by letting him confirm equal loading on each side before pushing into an unfamiliar, longer range of motion. He says a pair of dumbbells serves the same purpose if that specific machine isn''t available.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Chest Workout Breakdown'),
('periodization', 'superset-based session restructuring for time efficiency', 'With limited time available, Bumstead restructured a chest-and-back day into three exercise pairs performed as supersets — a compound pulldown paired with a compound press, then isolation pullover and pec-deck work — explicitly describing this as a deliberate, temporary efficiency change from his normal training rather than his default approach.', 'practice', 'weak', NULL, '{"note": "3 exercise pairs supersetted back-to-back; 4 sets of each isolation movement"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Chest Workout Breakdown'),
('guideline', 'bench press 1RM benchmarks by training age', 'Greg Doucette presents a self-reported survey of his (self-selected, gym-going) audience showing average bench 1RM of roughly 185 lb under 6 months of training, 220 lb at 6 months to 2 years, 235 lb at 2 to 5 years, 275 lb at 5 to 10 years, and 285 lb at 10-plus years, with 95th-percentile (“elite”) lifters at roughly 275 / 315 / 320 / 365 / 405 lb at those same milestones. Because this is a self-reported online survey of an already above-average, self-selected audience rather than a controlled study, the specific numbers should be treated as rough anecdote, not population data.', 'opinion', 'weak', NULL, '{"avg_1rm_lb": {"under_6mo": 185, "6mo_2yr": 220, "2_5yr": 235, "5_10yr": 275, "10yr_plus": 285}, "elite_95th_1rm_lb": {"under_6mo": 275, "6mo_2yr": 315, "2_5yr": 320, "5_10yr": 365, "10yr_plus": 405}}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — How Does Your Bench Press Stack Up?'),
('progression', 'strength-gain deceleration after roughly two years', 'In the same survey, the largest jump in average bench press occurs in the first two years of training (185 lb to 220 lb), after which average gains slow dramatically — only 220 lb to 235 lb across the entire 2-to-5-year window. Doucette links this deceleration to why he believes many lifters quit once the rapid early-training progress stops.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — How Does Your Bench Press Stack Up?'),
('guideline', 'bodyweight-for-reps bench benchmark', 'Doucette''s survey reports that an average lifter under about 210 lb bodyweight can bench their own bodyweight for roughly 10 to 11 reps, while a 95th-percentile (“elite”) lifter in that weight range can do 25-plus reps at bodyweight. For lifters heavier than about 240 lb, the average rep count with bodyweight on the bar drops off sharply (about 10.5 reps average at 240 lb down to essentially 0 reps average for those over 300 lb), which he attributes to bodyweight becoming a proportionally heavier absolute load as body mass increases.', 'opinion', 'weak', NULL, '{"avg_reps_at_bodyweight_under_210lb": 10.5, "elite_95th_reps_at_bodyweight_under_210lb": 25, "avg_reps_at_bodyweight_over_300lb": 0}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — How Does Your Bench Press Stack Up?'),
('guideline', 'scaling rest periods to the muscle/movement demand', 'Sam Sulek rests about 1 to 2 minutes between sets of the same movement, but extends rest to roughly 3 to 4 minutes on the most demanding compound leg work (e.g., heavy leg press) to let himself “reoxygenate,” while resting less than a minute between sets of light shoulder-pump work like side laterals. He frames rest length as movement- and muscle-specific (quads, the largest muscle, simply need longer recovery than something like rear-delt flies) rather than a single fixed number for every exercise.', 'practice', 'weak', NULL, '{"rest_same_movement_min_minutes": 1, "rest_same_movement_max_minutes": 2, "rest_heavy_compound_leg_minutes": 4, "rest_light_pump_work_minutes": 0.5}'::jsonb, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 18 - Legs - Hefty Leg Press'),
('volume', 'working-set time budget per body part', 'Sam Sulek estimates a full, hard chest session (working sets only, excluding warm-up) takes him about 30 to 45 minutes. On this leg day, hamstrings (6 working sets: leg curls plus RDLs) took roughly 30 to 40 minutes and quads (6 working sets: leg extensions plus leg press) a similar span; he estimates a maximally complete leg day covering hamstrings, adductors, quads, and calves at 8 sets each (32 sets total) could run about 2 hours.', 'practice', 'weak', NULL, '{"chest_working_set_minutes_low": 30, "chest_working_set_minutes_high": 45, "leg_day_hams_sets": 6, "leg_day_quads_sets": 6, "leg_day_full_sets_per_muscle": 8, "leg_day_full_total_sets": 32, "leg_day_full_hours_estimate": 2}'::jsonb, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 18 - Legs - Hefty Leg Press'),
('detraining', 'strength lost from a purely light, pump-focused block', 'Sam Sulek argues that if he trained only light “squeezing” sets to failure (e.g., light leg extensions) for two months at maintenance calories, he would come out of it noticeably weaker on heavy compound tests, because strength adapts specifically to the loads a lifter is actually exposed to. He uses this reasoning to justify keeping some heavy, low-rep-range pressing and squatting work in his program year-round rather than training only with light isolation pump work.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 18 - Legs - Hefty Leg Press'),
('progression', 'risk of testing a 1RM without recent low-rep exposure', 'Sam Sulek says he has not trained below an 8-rep working set on squats or bench for roughly the last 3 to 4 years, and believes that if he tried to work up to a true 1-rep max now without a proper build-up he would very likely tear a pec or a quad. His view is that occasional heavy singles are fine only for lifters who build up to them gradually and stay exposed to that rep range, not as a cold test.', 'opinion', 'weak', NULL, '{"years_without_sub_8rep_training": 3.5}'::jsonb, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 18 - Legs - Hefty Leg Press'),
('progression', 'capacity to reach true failure improves with training age', 'Sam Sulek says the ability to push a set to genuine muscular failure is itself a trained skill, not a fixed trait: early in his training he could not select a weight and actually hit a prescribed rep target (e.g., a true 12-rep max) because he had not yet built the tolerance to exert himself that hard, and would have needed a lighter weight than he was truly capable of lifting. He describes that capacity for effort as having increased over years of deliberately pushing hard sets.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 18 - Legs - Hefty Leg Press'),
('guideline', 'spotting whether a lifter actually trained to failure', 'Sam Sulek says a red flag that a set was not taken close to failure is when the last rep looks the same speed and ease as the first rep. He relates a secondhand story of a lifter who intended to rack a pendulum-squat set at 12 reps but, pushed on by training partners, actually completed 30 reps — illustrating how far off a lifter''s own sense of their failure point can be.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 18 - Legs - Hefty Leg Press'),
('strength-accessories', 'cable leg curl setup preferred over standard lying curl', 'For hamstring curls, Sam Sulek prefers a cable curl setup with a small platform to stand on (which lets him get a deep stretch) over a standard lying leg-curl machine, saying he can “squeeze it better” in that position.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 18 - Legs - Hefty Leg Press'),
('tempo', 'peak-hold into forced reps on leg extensions', 'On single-leg leg extensions taken to failure, Sam Sulek pauses/holds at the top (peak contraction) for roughly the first 10 reps of a set; once he''s too fatigued to hold the pause, he intentionally switches to using body English/swing to force out a few more reps rather than stopping, treating this as a deliberate technique to extract more from the set rather than sloppy form.', 'practice', 'weak', NULL, '{"note": "top-of-rep pause held for roughly the first 10 reps of a leg-extension set, then form loosens intentionally to force extra reps"}'::jsonb, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 18 - Legs - Hefty Leg Press'),
('equipment', 'using a mechanical safety catch to enable true failure training', 'Sam Sulek deliberately trains leg press heavy to true failure because the machine has a mechanical safety catch, which removes his fear of being pinned under the weight if he fails a rep. He contrasts this with incline barbell bench, which he trains unspotted, saying he wishes safety catches were more standard on incline barbell setups given how risky failing a rep there feels by comparison.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 18 - Legs - Hefty Leg Press'),
('volume', 'diminishing returns from adding sets past sufficiency', 'Sam Sulek says adding extra heavy leg-press sets on top of an already-sufficient quad session would not add meaningfully more stimulation than what he had already done (leg extensions plus leg press), comparing it to hammering a nail past the point it''s already flush with the wall. He describes deliberately stopping a muscle group once additional sets stop adding quality stimulation rather than adding volume for its own sake.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 18 - Legs - Hefty Leg Press'),
('tempo', 'convergence: peak-contraction squeeze/hold on isolation work', 'Two independent practitioners in this batch describe the same technique on isolation lifts: Chris Bumstead holds a full contraction for about 15 seconds on pullover and pec-deck work, and Sam Sulek pauses at the top of single-leg leg extensions for roughly the first 10 reps of a set. Both frame the pause as a deliberate way to intensify stimulus in the shortened position, suggesting a shared practice among these high-reach bodybuilders even though neither attributes it to a specific study.', 'practice', 'moderate', NULL, NULL, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 18 - Legs - Hefty Leg Press'),
('volume-per-muscle', 'Fatigue-based set count rather than fixed target', 'Sam Sulek does not target a fixed number of sets per muscle; he trains to a subjective point of fatigue, which has historically landed around 7-8 sets for an arm muscle in a session, though some sessions he stops at 4-5 sets once the muscle feels fully worked.', 'practice', 'weak', NULL, '{"typical_sets_per_muscle": "7-8", "note": "sometimes as few as 4-5 sets when fatigue/pump arrives sooner; endpoint is a felt fatigue threshold, not a rep/set target"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 35 - Arms - Baby Sets = Baby Gains'),
('progression', 'Eight-rep floor for working sets', 'Sam Sulek treats 8 reps as the practical minimum for an effective hypertrophy working set (up to about 25-30 reps at the top end); if a chosen weight only allows fewer than 8 reps he converts the set into a rest-pause or drop set to reach 8, rather than treating the heavy low-rep attempt itself as the working set.', 'practice', 'weak', NULL, '{"min_reps": 8, "note": "top end roughly 25-30 reps; if a weight yields under 8 reps he rest-pauses or drop-sets down in load to finish the set rather than counting the low-rep attempt as a working set"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 35 - Arms - Baby Sets = Baby Gains'),
('tempo', 'Alternating heavy sets with light squeezing sets in the same session', 'Sam Sulek deliberately alternates heavy sets close to failure with lighter, paused/squeezing sets emphasizing peak contraction and stretch within the same arm session, saying each style stimulates something the other misses (mechanical tension from heavy loading vs. burn/stretch/pump from light squeezing work).', 'practice', 'weak', NULL, '{"note": "no fixed ratio given; heavy work roughly in an 8-rep range paired with lighter squeezing work roughly in a 15-20+ rep range"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 35 - Arms - Baby Sets = Baby Gains'),
('strength-accessories', 'Rope vs. straight-bar pushdown for triceps', 'Sam Sulek prefers the rope attachment over a straight bar for triceps pushdowns because pulling the rope ends apart at the bottom of the rep changes the resistance curve, adding load specifically near full elbow extension/peak contraction, whereas a straight bar feels like a constant weight throughout the range.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 35 - Arms - Baby Sets = Baby Gains'),
('strength-accessories', 'Self-assisted concentration curls past failure', 'Sam Sulek extends single-arm concentration curl sets past strict failure by using his free hand to help pull the dumbbell through the last few reps once he can no longer complete the movement unassisted, treating this as a way to keep loading the biceps after strict-form failure is reached.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 35 - Arms - Baby Sets = Baby Gains'),
('progression', 'Avoids 1-rep-max testing in normal training', 'Sam Sulek says he stopped attempting 1-rep maxes after his first roughly two years of training and now considers repeated higher-rep working sets (8+ reps to real fatigue) the actual driver of long-term size and strength, viewing max testing as only a way to check current strength, not a way to build it; if a max attempt is done, he recommends a slow incremental warm-up followed by an immediate return to normal working sets afterward.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 35 - Arms - Baby Sets = Baby Gains'),
('strength-accessories', 'Direct forearm work required for forearm growth', 'Sam Sulek argues incidental forearm loading from heavy back movements is not sufficient stimulus for forearm growth and that direct forearm training (curls/extensions) is required; he points to the dominant arm typically having a visibly bigger forearm than the non-dominant arm as evidence that more direct use drives more growth.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 22 - Forearms and Calves'),
('equipment', 'Straps to isolate the back from grip limitation', 'Sam Sulek uses lifting straps on back pulling movements specifically because, without them, grip/forearm fatigue becomes the limiting factor before the lats and traps are fully worked, and near failure on strapless back sets he feels the load shifting into forearm-extensor musculature rather than staying on the back.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 22 - Forearms and Calves'),
('strength-accessories', 'Grip technique on wrist curls', 'On dumbbell wrist curls (flexor work) Sam Sulek keeps a firm, fixed grip through the full range rather than letting the dumbbell roll down toward the fingers before squeezing it back into the palm, saying he prefers the simpler fixed range of motion over the finger-roll variation.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 22 - Forearms and Calves'),
('strength-accessories', 'Bent-knee vs. straight-leg calf raises target different heads', 'Sam Sulek distinguishes seated, bent-knee calf machine work from straight-leg calf raises (standing or on leg press), saying straight-leg movements give more activation to the larger upper part of the calf (gastrocnemius) and was planning to add more straight-leg work back in after a stretch of doing mostly seated bent-knee sets.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 22 - Forearms and Calves'),
('strength-accessories', 'Single-leg calf raises to manage side-to-side imbalance', 'Sam Sulek does calf raises one leg at a time rather than both together, saying a perceived imbalance between his two calves makes bilateral raises load one side more than the other, and single-leg work lets him load each side evenly.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 22 - Forearms and Calves'),
('volume', 'Low-cost accessory add-ons at end of any session', 'Sam Sulek treats forearm and calf work as cheap additions to any training day, saying that tacking them onto the end of a session for another muscle group adds time but not much additional systemic fatigue, so he recommends using would-be rest days (or session ends) for these smaller muscle groups rather than skipping them.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 22 - Forearms and Calves'),
('strength-accessories', 'Sumo deadlift as primary hamstring builder', 'Greg Doucette rates the sumo deadlift as his best hamstring exercise for himself personally, citing a strong hamstring stretch and feel and, given his own back history (a longstanding L4-L5 herniated disc), less lower-back strain than conventional-stance deadlift variants.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Shredded HAMSTRINGS || Best & Worst Exercises'),
('progression', 'Regressing the glute-ham raise for less advanced lifters', 'Greg Doucette recommends hinging further forward at the hip on the glute-ham raise to make it easier for less advanced lifters, targeting 10+ reps per set for time under tension, using a slower eccentric than concentric, and stopping short of full range at the bottom rather than chasing a deeper stretch.', 'opinion', 'weak', NULL, '{"target_reps": "10+", "note": "hinge forward at the hip to regress difficulty; eccentric slower than concentric; do not need to reach full bottom range"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Shredded HAMSTRINGS || Best & Worst Exercises'),
('strength-accessories', 'Leg curl (seated or lying) as the default hamstring exercise for any level', 'Greg Doucette ranks the seated or lying leg curl as the single most important hamstring exercise for beginner through advanced lifters, valuing it above harder movements specifically because it is safer and lower-skill (harder to perform dangerously), and treats seated and lying variants as roughly interchangeable in effectiveness.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Shredded HAMSTRINGS || Best & Worst Exercises'),
('strength-accessories', 'Foot placement on leg press/hack squat/Smith squat shifts hamstring vs. quad emphasis', 'Greg Doucette says placing the feet higher, further forward, and wider on a leg press, hack squat, V-squat, or Smith squat platform shifts emphasis toward the hamstrings and glutes, while a low, narrow foot position (his own preference) shifts emphasis toward the quads; he considers toe angle (straight, in, or out) a matter of individual feel rather than something with a consistent hamstring-bias effect.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Shredded HAMSTRINGS || Best & Worst Exercises'),
('volume-per-muscle', 'Weekly hamstring set volume and split', 'Greg Doucette recommends 10-20 total weekly sets for hamstrings, split across two sessions (roughly 5-10 sets per session), with beginners targeting about 5 sets per session and more advanced lifters targeting about 10 per session, contingent on recovering (not being more sore than the prior session) before adding more.', 'opinion', 'weak', NULL, '{"sets_per_week_min": 10, "sets_per_week_max": 20, "sessions_per_week": 2, "beginner_sets_per_session": 5, "advanced_sets_per_session": 10}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Shredded HAMSTRINGS || Best & Worst Exercises'),
('strength-accessories', 'Half-depth squats undertrain hamstrings and glutes', 'Greg Doucette says squatting only to a partial, above-parallel depth builds quads but gives comparatively little hamstring or glute activation, and that full range of motion to at least parallel is needed to meaningfully load the hamstrings on any squat-pattern exercise (leg press, Smith squat, hack squat, etc.).', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Shredded HAMSTRINGS || Best & Worst Exercises'),
('strength-accessories', 'Avoid full lockout on stiff-leg deadlift to keep hamstring tension', 'Greg Doucette recommends stopping the stiff-leg deadlift short of full lockout at the top (he estimates around 70 degrees of hip extension rather than fully upright) to keep constant tension on the hamstrings, keeping a slight knee bend throughout rather than locking the knees, and using light weight until the technique is mastered because he considers it an easy exercise to get hurt on.', 'opinion', 'weak', NULL, '{"note": "stop short of full lockout, roughly 70 degrees of hip extension; maintain a slight knee bend; use light weight until technique is mastered"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Shredded HAMSTRINGS || Best & Worst Exercises'),
('strength-accessories', 'Standing single-leg leg curl machine rated worst hamstring exercise', 'Greg Doucette calls the standing single-leg hamstring curl machine his least favorite hamstring exercise because its strength curve is mismatched to the muscle''s leverage: the movement is very easy at the bottom and very hard near full contraction at the top, so any weight heavy enough to be challenging at the bottom cannot be curled through a full range, forcing partial reps or very light loads.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Shredded HAMSTRINGS || Best & Worst Exercises'),
('strength-accessories', 'Adductor training improves squat stability', 'Sam Sulek says that when he trains his adductors consistently he feels noticeably more stable side-to-side in a heavy squat, and that skipping adductor work for a while makes him feel wobblier under a heavy squat, treating direct adductor work as functionally supporting his squat stability rather than purely cosmetic.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Spring Cut Day 58 - Quads Hams Adductors and Calves'),
('progression', 'Warm-up sets are light and low-rep, not fatiguing', 'Sam Sulek''s warm-up protocol for a heavy compound lift is several short sets of 2-3 reps at progressively heavier (but still light) loads, explicitly meant to raise tissue readiness for a heavy set without inducing meaningful fatigue before the real working sets begin.', 'practice', 'weak', NULL, '{"warmup_reps_per_set": "2-3", "note": "load increases gradually across several short sets; purpose is joint/muscle readiness, not stimulus"}'::jsonb, 'Sam Sulek (high-volume physique training) — Spring Cut Day 58 - Quads Hams Adductors and Calves'),
('tempo', 'Varying rep speed within a set/session for stimulus variety', 'Sam Sulek mixes tempos within his heavy leg sets — an explosive concentric with a brief hold at the top and a slower negative on some reps — and argues that lifters who only ever use one tempo (e.g., always slow and controlled) may be missing stimulus variability, so he deliberately throws in faster, more explosive sets periodically alongside controlled ones.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Spring Cut Day 58 - Quads Hams Adductors and Calves'),
('strength-accessories', 'Deliberately submaximal loading on RDL to keep tension on hamstrings', 'Sam Sulek caps his Romanian deadlift loading (citing roughly two plates per side on a Smith machine as a personal ceiling) because going heavier shifts the load into the glutes and lower back rather than the hamstrings; he frames the RDL''s purpose as hamstring-specific loading, not maximal load moved.', 'practice', 'weak', NULL, '{"self_reported_load_cap": "roughly 2 plates per side (Smith machine RDL)", "note": "heavier loading noted as shifting emphasis to glutes/lower back away from hamstrings"}'::jsonb, 'Sam Sulek (high-volume physique training) — Spring Cut Day 58 - Quads Hams Adductors and Calves'),
('strength-accessories', 'Single-leg-to-double-leg pre-exhaust superset for hamstring burnout', 'Sam Sulek finishes hamstrings with a superset on the leg curl machine: alternating single-leg reps (about 5 per side, back and forth) until fatigued, then switching to double-leg reps at a reduced weight to burn out further, describing it as a way to maximize localized hamstring fatigue at the end of the muscle''s work for the day.', 'practice', 'weak', NULL, '{"single_leg_reps_per_side": 5, "note": "alternates single-leg reps to fatigue, then drops load and continues double-leg to burn out"}'::jsonb, 'Sam Sulek (high-volume physique training) — Spring Cut Day 58 - Quads Hams Adductors and Calves'),
('equipment', 'Leg extension cam geometry changes where in the range resistance feels heaviest', 'Sam Sulek describes the standard round-cam leg extension machine as keeping resistance roughly even throughout the range of motion (because the cable-pulling cam is close to circular), in contrast with other leg extension designs where the load is heavier at the bottom and lighter near lockout; he says this changes both where in the rep he feels the most quad tension and what failure looks like on a given machine (an abrupt stall vs. a gradually slowing bar path).', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Spring Cut Day 58 - Quads Hams Adductors and Calves'),
('strength-accessories', 'contradiction: exercise order (isolation before compound)', 'Sam Sulek deliberately pre-fatigues his quads with leg extensions before his heaviest compound lift of the day (Smith machine squats), preferring to squat with a residual pump rather than doing the compound lift first. This runs counter to the common strength/hypertrophy programming guideline of performing the heaviest, most technically demanding compound lift first in a session while fresh, with isolation/accessory work placed afterward; pre-fatigue sequencing like this is generally understood to reduce the load that can safely and effectively be used on the compound lift.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Spring Cut Day 58 - Quads Hams Adductors and Calves'),
('volume-per-muscle', 'Cautious, moderate-volume adductor accessory work', 'Sam Sulek treats the adductor (hip adduction) machine as light accessory work: about 5-6 sets of moderate, not-to-failure loading, explicitly warning that this movement is easy to strain and that ego-lifting on it can compromise squat performance afterward, so he airs on the side of lighter loads there even when he otherwise trains close to failure.', 'practice', 'weak', NULL, '{"sets": "5-6", "note": "moderate load, not taken to full failure; explicit injury caution on this machine"}'::jsonb, 'Sam Sulek (high-volume physique training) — Spring Cut Day 58 - Quads Hams Adductors and Calves'),
('strength-accessories', 'Gripping leg extension handles diverts load away from the legs', 'Ryan Humiston''s EMG testing on himself showed that gripping and pulling on the leg extension handles significantly reduced measured activation in every quad muscle compared to performing the same sets without holding on (using a toe strap instead to stay seated), leading him to recommend not gripping the handles if avoidable.', 'practice', 'weak', NULL, '{"note": "self EMG test; every measured quad muscle showed higher activation without hand-gripping the handles versus gripping/pulling"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — You Were Wrong Back By SCIENCE!'),
('strength-accessories', 'Toe pressure and foot height affect which quad muscle is emphasized', 'Ryan Humiston''s EMG testing found stance width had little effect on vastus lateralis activation, but pressing more weight through the toes increased rectus femoris activation regardless of stance, and lowering the foot position (more pressure through the toes at a lower foot placement) increased vastus medialis (VMO) activation the most.', 'practice', 'weak', NULL, '{"note": "self EMG test on leg press/leg extension; toe pressure drives rectus femoris activation; lower foot position plus toe pressure drives VMO activation most; stance width showed little effect on vastus lateralis"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — You Were Wrong Back By SCIENCE!'),
('strength-accessories', 'Foot rotation targets different hamstring heads', 'Ryan Humiston''s EMG testing found that turning the feet outward (external rotation) predominantly activates the biceps femoris (outer hamstring), while turning the feet inward shifts activation to the semitendinosus (inner hamstring), and that this held true on both a leg curl and a hip-hinge (RDL-style) movement; he recommends stiff-leg/hip-hinge work with feet turned out for outer-hamstring bias, and dumbbell leg curls (which force an inward foot/knee position to hold the dumbbell) for inner-hamstring bias.', 'practice', 'weak', NULL, '{"note": "self EMG test; external foot rotation biases biceps femoris, internal rotation biases semitendinosus, consistent across leg curl and hip-hinge patterns"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — You Were Wrong Back By SCIENCE!'),
('volume-per-muscle', 'Heavy low-rep vs. light high-rep leg extension work grew different quad muscles (relayed study)', 'Ryan Humiston relays a case study (MRI-tracked) in which training the leg extension exclusively in a 4-6 rep heavy range grew only the rectus femoris, while training exclusively in a 15-20 rep range grew only the vastus lateralis, suggesting load/rep range can bias which specific muscle within a muscle group responds, not just overall muscle-group growth.', 'opinion', 'weak', NULL, '{"heavy_condition_reps": "4-6", "light_condition_reps": "15-20", "note": "relayed from a study, not independently verified by the speaker; MRI-tracked per-muscle growth reported"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — You Were Wrong Back By SCIENCE!'),
('equipment', 'Heel elevation increases quad activation beyond just an ankle-mobility fix', 'Ryan Humiston tested placing plates under his heels on a leg exercise and found it increased EMG activation across every measured quad muscle, concluding that heel elevation is not just a workaround for people with poor ankle mobility but a technique that increases quad activation more generally.', 'practice', 'weak', NULL, '{"note": "self EMG test; heel-elevation plates increased activation across all measured quad muscles, not limited to lifters with ankle mobility limitations"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — You Were Wrong Back By SCIENCE!'),
('strength-accessories', 'Partial reps at long muscle length aid hypertrophy (relayed study, caveated)', 'Ryan Humiston relays a study finding that partial leg extension reps performed at the long/stretched end of the range of motion produced more hypertrophy than partials at the short end or full-range-of-motion reps, but flags the finding as lower-confidence because it was done on 20 untrained women, whose novice status (not their sex) makes them respond strongly to almost any stimulus.', 'opinion', 'weak', NULL, '{"note": "relayed from a study on 20 untrained subjects; speaker explicitly caveats generalizability due to untrained-population response"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — You Were Wrong Back By SCIENCE!'),
('volume-per-muscle', 'soreness-based training decision', 'Sam Sulek trains a fresh muscle group even when badly sore elsewhere; his rule is to skip training only the specific muscle that is itself sore, not skip the session outright. He trained chest hard the day after a leg session left his legs so sore he could barely jump, because his chest itself was not sore, but says he has skipped a muscle when that specific muscle was still sore (e.g., skipped hamstrings after prior hamstring-specific work).', 'practice', 'weak', NULL, '{"note": "decision rule is per-target-muscle soreness, not whole-body fatigue"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 37 - Chest - Lifting with Sore Legs'),
('periodization', 'reducing heavy compound work while dieting', 'During a diet/cut, Sam Sulek keeps overall leg training volume similar to a bulk but backs off heavy compound pressing work like Smith machine squats, judging squats too systemically taxing (bracing, lower back and glute drive) when recovery resources are limited and his goal is isolated quad growth.', 'practice', 'weak', NULL, '{"note": "volume roughly unchanged across diet phases; heavy compound pressing specifically reduced when dieting"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 37 - Chest - Lifting with Sore Legs'),
('strength-accessories', 'chest day exercise order and squeeze cues', 'Sam Sulek''s chest day: warm up on cables first, then several sets of Hammer Strength chest press done slow and controlled with a hard squeeze at the top and a full stretch at the bottom, then a bent-cable movement blending a fly and a press, finished with a pump-focused alternating single-arm cable press superset. He uses the same alternating single-arm cable technique on leg extensions and curls as well as chest.', 'practice', 'weak', NULL, '{"note": "finisher approx 5 reps per side, alternating sides back and forth"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 37 - Chest - Lifting with Sore Legs'),
('guideline', 'preferred rep range for hypertrophy', 'Sam Sulek considers roughly 8 reps the floor of a solid hypertrophy rep range, working up into the high teens or 20s, but avoids sets as high as 30 reps.', 'opinion', 'weak', NULL, '{"reps_min": 8, "reps_upper_range": 20, "reps_avoided_above": 30}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 37 - Chest - Lifting with Sore Legs'),
('progression', 'autoregulating load session-to-session', 'Sam Sulek argues a hypertrophy-focused lifter should not stress about day-to-day strength fluctuations and should use whatever weight feels right that session rather than forcing a fixed number, contrasting this with a powerlifter in a peaking week who cannot afford unpredictable strength swings.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 37 - Chest - Lifting with Sore Legs'),
('volume-per-muscle', 'temporarily deprioritizing a muscle group for proportion', 'Sam Sulek said he was pulling back on back training for a while (a deliberate, temporary reduction) to let his chest and arms catch up proportionally, judging his physique by how his side chest compares to his back and lats in a pose.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 37 - Chest - Lifting with Sore Legs'),
('tempo', 'squat depth for quad growth', 'Sam Sulek says many gym-goers squat far above parallel and that this costs gains beyond just reduced range of motion: he says a full stretch and full range let a lifter settle into a rhythmic groove within the rep that partial reps never achieve, and argues this applies to hypertrophy training even for lifters with no powerlifting depth requirement to meet.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 110 - Legs - Lean Into Your Strengths, Plus Some Crazy Leg Press'),
('strength-accessories', 'hamstrings-before-quads exercise order on a quad-priority day', 'On a leg day where quads are the priority, Sam Sulek trains hamstrings first, lighter and with fewer sets, rather than after quads. He reasons that warmed, pumped hamstrings cushion the knees at the bottom of a squat or leg press, whereas training hamstrings after a hard quad session would leave him too fatigued, mentally and physically, to execute the hamstring reps well.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 110 - Legs - Lean Into Your Strengths, Plus Some Crazy Leg Press'),
('progression', 'leg press failure target and inter-set load adjustment', 'Sam Sulek targets around 10 to 11 reps to failure on heavy leg press; if a following set at the same load falls to around 6 reps he still counts it as a good set, but treats that drop as his cue to remove a plate for the next set rather than repeating the same load.', 'practice', 'weak', NULL, '{"target_reps_to_failure": "10-11", "drop_load_trigger_reps": 6}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 110 - Legs - Lean Into Your Strengths, Plus Some Crazy Leg Press'),
('equipment', 'variable-resistance leg press vs straight-line sled', 'Sam Sulek prefers a leg press machine with a variable strength curve (lighter at the bottom of the rep, progressively heavier near lockout) over a straight-line sled leg press with constant resistance, reasoning it better matches the body''s natural squat and press strength curve, which is weakest deep in the hole and strongest near lockout.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 110 - Legs - Lean Into Your Strengths, Plus Some Crazy Leg Press'),
('periodization', 'alternating rep range across leg sessions to manage intensity', 'After a session where his heavy leg press sets landed around 6 to 11 reps to failure, Sam Sulek judged that intensity too dense and planned to make his next quad-focused leg day lighter and more endurance-based, including sets up to about 20 reps, deliberately alternating rep ranges across sessions rather than always training in the same range.', 'practice', 'weak', NULL, '{"session_reps_to_failure": "6-11", "planned_next_session_reps_to_failure": "up to 20"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 110 - Legs - Lean Into Your Strengths, Plus Some Crazy Leg Press'),
('tempo', 'controlled tempo on knee-heavy exercises', 'For leg press and leg extension work meant to protect his knees, Sam Sulek emphasizes a solid hold at the top, a slow negative, and deliberate, mindful squeezing rather than just adding weight or grinding out fast reps, saying this builds mechanical tension and control in a way that is easier on the knees than heavier, sloppier reps.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 110 - Legs - Lean Into Your Strengths, Plus Some Crazy Leg Press'),
('clinical', 'leg extension load caution for knee and hip flexor safety', 'Sam Sulek warns against maxing out weight on single-leg leg extensions, saying he has previously strained his upper quad near the hip flexor doing this, and specifically advises against loading leg extensions heavy for anyone with sore knees, preferring leg press or squat variations for going heavy.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 110 - Legs - Lean Into Your Strengths, Plus Some Crazy Leg Press'),
('strength-accessories', 'alternating antagonist supersets to preserve pump in both muscles', 'On arm day, Sam Sulek alternates back and forth between triceps and biceps movements in blocks of two sets rather than finishing one muscle before starting the other, reasoning that a muscle pump fades quickly, so fully finishing biceps first would leave triceps already deflated by the time he reached a triceps-focused finisher.', 'practice', 'weak', NULL, '{"note": "structure: 2 sets triceps, 2 sets biceps, 2 sets triceps, alternating, ending in a superset finisher"}'::jsonb, 'Sam Sulek (high-volume physique training) — Winter Bulk Day 5 - Back Rear Delts and Calves'),
('volume-per-muscle', 'reduced arm volume on a low-energy dieting day', 'On a lower-energy dieting day, Sam Sulek did about six sets of triceps and five sets of biceps for an arm workout, describing a roughly 5-to-7-sets-per-muscle range as lower than his usual arm volume because the muscles were getting fatigued faster than normal.', 'practice', 'weak', NULL, '{"triceps_sets": 6, "biceps_sets": 5, "typical_range_low_volume_day": "5-7 sets per muscle"}'::jsonb, 'Sam Sulek (high-volume physique training) — Winter Bulk Day 5 - Back Rear Delts and Calves'),
('volume', 'autoregulating training day vs rest day by feel', 'Sam Sulek decides whether the next day will be a training day or a rest day based on how he feels rather than a fixed schedule, saying he will train legs if he feels ready and take another rest day if he does not.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Winter Bulk Day 5 - Back Rear Delts and Calves'),
('progression', 'contradiction: reps-in-reserve coaching vs training near failure', 'Sam Sulek dismisses common reps-in-reserve coaching advice (e.g., training with around 5 RIR) as effectively a cop-out that lets inexperienced lifters avoid pushing hard, arguing that how close to failure and how hard someone trains matters more than which specific programming style (low volume/high intensity vs. high volume/short rest) they follow. This conflicts with the evidence-based view the corpus holds at strong confidence, that training a controlled distance from failure (roughly 1 to 5 RIR) produces hypertrophy similar to training to complete failure with less fatigue cost, so RIR-based programming is not simply an excuse to go easy.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 84  - Legs - Leg Press Is Back'),
('tempo', 'clean heavy set finished with partial reps', 'Sam Sulek''s default straight-set structure on leg day is a moderate-tempo set to failure with a momentary hold at the top, then continuing into a handful of partial-range reps once he can no longer complete a full rep, describing it as clean at the start and dirty at the end.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 84  - Legs - Leg Press Is Back'),
('strength-accessories', 'rest-pause technique to vary the fatigue curve', 'Sam Sulek deliberately switches some sets to a rest-pause structure: about 5 controlled reps short of failure, a roughly 10-to-15-second pause, then another ~5 reps, repeated until true failure is reached. He explains he likes it because it changes the shape of the fatigue curve (stop-start) compared to a straight set''s steady linear decline in energy, without claiming it recruits different fiber types.', 'practice', 'weak', NULL, '{"reps_per_cluster": 5, "rest_between_clusters_sec": "10-15"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 84  - Legs - Leg Press Is Back'),
('equipment', 'reading leg press resistance from sled angle; valuing built-in safety catches', 'Sam Sulek estimates that an unfamiliar leg press''s roughly 30-degree sled incline means he is only feeling about half of the stacked plate weight, and uses that estimate to pick a starting load. He also specifically values leg press machines with a safety catch that lets him push a set to genuine failure without needing a spotter.', 'practice', 'weak', NULL, '{"note": "sled incline approx 30 degrees, estimated felt load approx 50% of stacked plate weight"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 84  - Legs - Leg Press Is Back'),
('progression', 'improved mind-muscle isolation with training experience', 'Sam Sulek says the leg press now feels like almost pure quad activation with zero glute involvement at heavy loads, versus feeling it mostly in his glutes when he was younger and lighter. He attributes this to years of training improving his ability to isolate the target muscle and waste less energy through synergists, using a lat pulldown example where a beginner''s forearms, biceps, and shoulders fatigue before the lats do, cutting the set short before the target muscle is properly worked.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 84  - Legs - Leg Press Is Back'),
('strength-accessories', 'combining heavy low-rep sets with light squeeze-focused sets in one session', 'Sam Sulek pairs a couple of heavy sets to failure on a lift like lying leg curl with sets at roughly a quarter of that weight done slow, with a deliberate hold in the stretched position. He argues a set''s effectiveness does not require heavy load, and recommends staying spread across that heavy-to-light continuum within a session rather than training only at one end of it.', 'opinion', 'weak', NULL, '{"note": "example: 2 heavy sets, then load dropped to roughly 1/4 for light squeeze sets"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 84  - Legs - Leg Press Is Back'),
('periodization', 'introducing novel exercise variations to break staleness', 'Sam Sulek periodically introduces a movement or technique he has not used before (e.g., a paused-bottom rep style on leg press for the first time) specifically to shock a muscle when training feels stale, and argues the resulting extra soreness reflects the novelty of the stimulus to that muscle rather than the new method being inherently superior to what he was doing before.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 84  - Legs - Leg Press Is Back'),
('equipment', 'choosing gyms and bench models for heavy dumbbell pressing safety', 'Sam Sulek picks gyms partly by bench model for heavy dumbbell work, preferring benches with a seat that racks higher and wider support, because at his working weight of up to about 150 lb dumbbells, a bench with the wrong angle or a seat that does not scoot up far enough makes him feel he could slip out of position while pressing that much weight overhead.', 'practice', 'weak', NULL, '{"working_dumbbell_weight_lb": 150}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 84  - Legs - Leg Press Is Back'),
('strength-accessories', 'row order to spare lower back', 'Bumstead sequences back day with a non-chest-supported hinge row (e.g. barbell row) first, then chest-supported dumbbell rows second, specifically so the lower back does not take repeated strain across the session. He called chest-supported dumbbell rows one of his favorite back exercises because varying hand pronation (pronated vs semi-pronated) lets him feel the squeeze in different parts of the back without loading the lower back.', 'practice', 'weak', NULL, '{"note": "chest-supported dumbbell rows added to his program roughly 3-4 years before this video"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Biceps and Eating Five Guys'),
('volume-per-muscle', 'extra weekly volume on a lagging muscle', 'Bumstead trains back twice a week with deliberately high volume (14 total sets across two exercises in this session alone, done the day after a hard leg session) because back is his stated weak point relative to the rest of his physique.', 'practice', 'moderate', NULL, '{"sets_this_session": 14, "frequency_per_week": 2}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Biceps and Eating Five Guys'),
('progression', '10x10 descending-load block', 'As the second exercise for a few body parts, Bumstead runs a ''10x10'' block: 10 sets aiming for 10 reps with descending load each set. He used it on hack squat the prior day (after 3 sets of 6-rep-max pendulum) and on chest-supported rows this session, describing it as severe enough to leave him extremely sore and fatigued the next morning.', 'practice', 'weak', NULL, '{"sets": 10, "target_reps_per_set": 10, "load_pattern": "descending"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Biceps and Eating Five Guys'),
('tempo', 'explicit tempo prescription to build mind-muscle connection', 'Bumstead now trains with a numeric tempo code (e.g. a biceps curl at ''3-1-1-0'': 3s negative, 1s pause at the bottom, 1s to lift, no pause at the top). He says that before adopting explicit tempo he could get a strong mind-muscle connection everywhere except back and biceps despite heavy ''ego lifting,'' and that switching to controlled tempo with lighter loads, not more weight, is what finally let those two muscles grow.', 'practice', 'weak', NULL, '{"tempo_code": "3-1-1-0", "meaning": "eccentric 3s, bottom pause 1s, concentric 1s, top pause 0s"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Biceps and Eating Five Guys'),
('strength-accessories', 'practical rep ceiling before tension breaks down', 'On an arm accessory superset (pullover + fat-grip preacher curl machine), Bumstead says his body ''is not built for 15 reps'' and that past roughly 10 reps the set ''just breaks down,'' treating around 10 reps as the point where the movement stops being productive rather than pushing for higher-rep burnout sets.', 'practice', 'weak', NULL, '{"approx_rep_ceiling": 10}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Biceps and Eating Five Guys'),
('strength-accessories', 'cues to deactivate hip flexors and control the spine on a weighted ab raise', 'On garhammer raises, Bumstead was coached to rotate his knees inward and bring his feet together (rather than keeping knees straight and in line with the torso) to reduce hip-flexor involvement, to lower one vertebra at a time instead of letting the lower back ''flop'' at the bottom, and to keep constant tension rather than reaching a full stretch, framing ab training as primarily about control rather than range of motion.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Biceps and Eating Five Guys'),
('guideline', 'personal precedent for combining endurance training with lifting long-term', 'Greg Doucette says he did 13 years of triathlon training (swimming, cycling, running) combined with lifting weights, from age 13 to 26, and made size and strength gains every year in that period while also winning national titles in both bodybuilding and powerlifting, offering it as personal evidence that concurrent endurance and strength training does not have to prevent meaningful muscle and strength gains.', 'practice', 'weak', NULL, '{"years": 13, "age_range": "13-26"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — How To Build Muscle While Running?'),
('guideline', 'separate cardio and lifting sessions to limit interference', 'Doucette recommends against doing a hard cardio session immediately before or after a lifting session on the same day, calling that combination ''too much'' and effectively overtraining, and advises splitting cardio and weights into separate sessions if the goal is to keep both endurance and hypertrophy gains.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — How To Build Muscle While Running?'),
('guideline', 'eccentric load of the cardio modality matters more than cardio itself', 'Doucette argues running carries an unusually large eccentric load (repeated single-leg landing impacts) compared to other cardio, and recommends lifters who want to maximize muscle growth choose a lower-impact modality such as cycling instead, citing his own move to cycling as letting him do long cardio sessions without getting sore enough to affect his lifting.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — How To Build Muscle While Running?'),
('guideline', 'low-dose cardio threshold unlikely to meaningfully cost strength/hypertrophy gains', 'Doucette states that aerobic training a couple of times per week for 30 minutes or less is unlikely to meaningfully interfere with strength or muscle gains, that beginners in particular can add cardio without noticeable hypertrophy cost, and that already well-muscled/advanced lifters are the ones most susceptible to losing gains from the same amount of running.', 'opinion', 'weak', NULL, '{"cardio_session_minutes": 30, "sessions_per_week": 2}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — How To Build Muscle While Running?'),
('progression', 'cycling heavy and light phases on the same movement to avoid staleness', 'Sulek deliberately alternates phases of training a given muscle: a stretch of light, slow, controlled high-rep ''squeezing'' work followed by a return to heavy, near-failure loading. He says the body ''gets used to'' whatever training you''re doing at any given moment, so he treats periodic in-and-out changes in load/tempo as useful on their own, independent of any specific hypertrophy mechanism he can name. Example given: seated hamstring curl, roughly two weeks of light ~15-rep squeezing work, then a return to heavy near-failure sets.', 'practice', 'moderate', NULL, '{"note": "example cycle roughly 2 weeks light/high-rep before returning to heavy loading"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 30 - Back and Forearms'),
('strength-accessories', 'splitting forearm training by sub-region, and deliberately under-training one portion', 'Sulek splits direct forearm work into the flexor/grip side (trained first, more volume) and a wrist-extension ''opening the hand'' portion (trained less). He believes over-developing the extensor/top portion specifically can give the forearm an unbalanced look, so he intentionally limits direct work there relative to the flexor/grip side.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 30 - Back and Forearms'),
('strength-accessories', 'forearm accessory set and rep scheme', 'For direct forearm training, Sulek does roughly five to six sets per side of light dumbbell curls and reverse curls with about a 20 lb dumbbell, taking each set to a burning sensation in the 15-20 rep range rather than a fixed rep target.', 'practice', 'weak', NULL, '{"sets": "5-6", "reps": "15-20", "load_lb": 20}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 30 - Back and Forearms'),
('volume-per-muscle', 'cutting frequency on an already-strong muscle to redirect recovery to lagging ones', 'Sulek says back is already his strongest, most developed body part relative to his frame, and in this session decided to cut back training to once a week going forward, replacing the freed-up volume with more calf and forearm accessory work. His stated reasoning is that reducing stress on an already-strong muscle frees up recovery capacity for his lagging arms, chest, and legs.', 'practice', 'moderate', NULL, '{"back_frequency_per_week": 1}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 30 - Back and Forearms'),
('volume-per-muscle', 'training a fast-recovering muscle at higher frequency, gated by soreness not a fixed schedule', 'Sulek trains calves whenever they are not sore rather than on a fixed weekly schedule, saying that if sleep and food have been on point he can often hit calves again as little as two days after the previous session, treating calves as unusually fast-recovering and tolerant of much higher frequency than back or legs.', 'practice', 'weak', NULL, '{"min_days_between_sessions": 2}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 30 - Back and Forearms'),
('clinical', 'grip strength as a subjective daily readiness check', 'Sulek uses how strong his resting grip/fist feels as an informal readiness check before a lift, saying it noticeably tracks how well he slept, ate, and hydrated. If his grip feels weak walking into the gym on a day he had planned a maximal or novel heavy set, he treats that as a cue to scale the session back rather than attempt the planned max effort.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 30 - Back and Forearms'),
('strength-accessories', 'grip width and scapular cue to deepen the stretch on a pulling movement', 'During this session one of the lifters is coached to widen his grip at the bottom of the rep and emphasize scapular protraction and retraction (reaching the shoulder blades forward at the bottom, pulling them back at the top) to get a deeper stretch, and to pull from the elbows rather than the wrists/forearms by keeping the arms positioned wider on the pulling movement.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Back & Biceps with the TREN TWINS'),
('tempo', 'full range of motion favored over partial-ROM loading for back growth', 'The group agreed that training with a full stretch and full range of motion on pulling movements is what drives back growth (''that''s how you get big''), and that training with a shortened range of motion lets a lifter get artificially strong in that partial range. They noted that returning to full range of motion after a period of partial-ROM training makes the same weight feel much weaker because the motor pattern has to be rebuilt.', 'opinion', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Back & Biceps with the TREN TWINS'),
('volume-per-muscle', 'individualizing training frequency per muscle based on how developed it is', 'Bumstead described his approach to bringing up a lagging muscle: if chest is already strong, train it only once every 10 days so it does not shrink, while training a lagging muscle like triceps up to three times in that same window so it can catch up, framing frequency as the main lever for correcting an imbalance rather than total weekly set volume alone.', 'opinion', 'moderate', NULL, '{"strong_muscle_frequency_days": 10, "lagging_muscle_sessions_per_window": 3}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Back & Biceps with the TREN TWINS'),
('progression', 'building a strength base before refining mind-muscle connection', 'Bumstead argued it is easier to learn mind-muscle connection and training nuance after already having built a strength base through heavier, more powerlifting-style training, than it is to learn how to train hard enough after starting from an isolation- and feel-focused approach, because training without a strength base makes it harder to judge whether you are actually pushing hard enough.', 'opinion', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Back & Biceps with the TREN TWINS'),
('equipment', 'free-weight substitutes for machines, and machines valued for removing core involvement', 'The Tren Twins train back mostly with deadlifts and dumbbell rows because their home gym has minimal equipment. The group noted that although machine rows are not strictly necessary, they are helpful for a bodybuilder specifically because they remove the core/stabilization demand and let the back be isolated more directly than a free-weight hinge movement.', 'opinion', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Back & Biceps with the TREN TWINS'),
('clinical', 'stopping immediately at the first sign of a muscular pull', 'When Sulek felt a burning/pulling sensation in his pec on a heavy incline press rep, he stopped the set immediately and abandoned chest training for the day rather than trying to finish reps or work around it. His stated rule is to ''take your foot off the brakes immediately'' at the first sign something feels off, contrasting this with past instances where he pushed through a similar sensation for a few extra reps and made the injury worse.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Winter Bulk Day 73 - Chest Injury, Back Instead'),
('equipment', 'cable ankle-strap substituted for a handle to train around a hand injury', 'For hand injuries that prevent gripping a handle, Sulek straps a cable ankle attachment around the forearm instead so curls, pushdowns, and presses can still be loaded without gripping, arguing that keeping some loaded movement and blood flow through an injured limb''s muscles preserves far more of the muscle than stopping training on it entirely.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Winter Bulk Day 73 - Chest Injury, Back Instead'),
('strength-accessories', 'different spinal-position standard on cable rows versus barbell rows', 'Sulek allows some spinal flexion/extension (a rounded lower back) on seated cable rows to get a fuller stretch at the bottom of the rep, but keeps a strict, non-rounded back specifically on bent-over barbell rows, treating the two exercises as needing different technique standards for the same muscle group.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Winter Bulk Day 73 - Chest Injury, Back Instead'),
('strength-accessories', 'single-arm rows preferred over bilateral chest-supported rows for breathing comfort', 'Sulek prefers doing rowing-machine work one arm at a time rather than both arms simultaneously on a chest-supported unit, because pressing his chest into the pad on both sides at once compresses his chest and makes it harder to breathe during the set.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Winter Bulk Day 73 - Chest Injury, Back Instead'),
('strength-accessories', 'adjusting incline angle to bias chest load away from front delts', 'Sulek lowered his incline press bench-angle setting from 3 to 2 specifically to shift more load onto chest and reduce front-delt involvement, and speculated after his pec strain that the lower angle combined with a heavy weight may have contributed to the injury.', 'practice', 'weak', NULL, '{"incline_setting_before": 3, "incline_setting_after": 2}'::jsonb, 'Sam Sulek (high-volume physique training) — Winter Bulk Day 73 - Chest Injury, Back Instead'),
('progression', 'fixed heavy-press block followed by an open squeeze-work block on chest day', 'Sulek''s default chest-day structure is a fixed opening block of heavy pressing (dumbbell, barbell, or Smith incline press, typically 3-4 hard sets), followed by an open second block of flies, lighter pressing, or cable/pec-deck squeeze work continued until he gets a satisfying pump, rather than a fixed exercise list for the back half of the session.', 'practice', 'weak', NULL, '{"heavy_press_sets": "3-4"}'::jsonb, 'Sam Sulek (high-volume physique training) — Winter Bulk Day 73 - Chest Injury, Back Instead'),
('clinical', 'contradiction: accepting periodic training injuries as the cost of training to failure', 'Sulek says he would ''rather get hurt every so often than train like a coward and never be injured,'' explicitly preferring heavy near-failure training that occasionally causes minor strains (he estimates roughly one significant tweak per 350 or so sessions) over slower, lighter, fully-controlled training. This stance conflicts with mainstream progressive-overload and RIR-based coaching guidance, which treats managed proximity-to-failure specifically as a tool to reduce injury risk rather than an acceptable trade-off against it.', 'opinion', 'weak', NULL, '{"self_reported_injury_rate": "roughly 1 per 350 sessions"}'::jsonb, 'Sam Sulek (high-volume physique training) — Winter Bulk Day 73 - Chest Injury, Back Instead'),
('clinical', 'training unaffected body parts hard through an injury, and belief that a calorie surplus speeds recovery', 'Sulek''s practice when injured is to keep training every unaffected body part as hard as possible rather than reducing overall training volume, and to keep eating in a calorie surplus. His stated (uncited) reasoning is that higher food intake and continued training keep metabolism and blood flow elevated and thereby speed recovery of the injured area faster than resting completely, and that lifters who stop training entirely after an injury take longer to return to baseline.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Winter Bulk Day 73 - Chest Injury, Back Instead'),
('volume', 'training frequency and rest days', 'Sam Sulek trains nearly every day with very few planned rest days, arguing that most unplanned rest days are driven by not feeling like it rather than genuine physiological need, provided food, sleep, and hydration are dialed in; he uses low-fatigue days (forearms/calves) as a substitute for a full rest day since they don''t tax the CNS the way a heavy chest or leg day does.', 'practice', 'weak', NULL, '{"note": "roughly 6 days/week training, low-fatigue muscle groups used as active-recovery days rather than full rest"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 108 - Forearms and Calves - Work a Muscle To Grow a Muscle'),
('strength-accessories', 'exercise variety vs. set count per exercise', 'Sam Sulek deliberately limits how many different exercises he uses per muscle group, preferring several hard working sets on one movement before moving to the next rather than a couple of sets across many different movements, reasoning that the muscle responds to tension and fatigue regardless of the exact exercise chosen.', 'opinion', 'weak', NULL, '{"note": "prefers e.g. 3-5+ working sets on one movement, then move on, rather than 2-3 sets across 6 movements"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 108 - Forearms and Calves - Work a Muscle To Grow a Muscle'),
('tempo', 'matching exercise variant to desired strength curve', 'Sam Sulek chooses between exercise variants (e.g. a standard dumbbell curl vs. a preacher-style curl) based on where each variant''s resistance curve places peak tension, using a preacher-style movement specifically when he wants to emphasize the squeeze at the top of the rep since a standard curl goes light at the top while a preacher curl stays loaded there.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 108 - Forearms and Calves - Work a Muscle To Grow a Muscle'),
('tempo', 'deliberately varying rep speed within a session', 'Sam Sulek uses slower, controlled, hard-squeeze reps on earlier working sets, then deliberately switches to quicker, higher-turnover reps on later sets (e.g. flies or a decline press) specifically to maximize a blood pump rather than to maximize tension.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 108 - Forearms and Calves - Work a Muscle To Grow a Muscle'),
('strength-accessories', 'prioritizing contraction/squeeze over load on isolation cable work', 'On forearm flexor cable work and light calf work, Sam Sulek intentionally underloads the weight and instead emphasizes squeezing through the full range (e.g. pulling the fingers toward the elbow on flexor cable curls) rather than chasing heavier weight, saying he now sees more value in these lighter ''squeezing sets'' than in going as heavy as possible.', 'practice', 'weak', NULL, '{"note": "e.g. reverse-wrist-curl work taken to a burning finish around 20 reps rather than loaded to failure"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 108 - Forearms and Calves - Work a Muscle To Grow a Muscle'),
('strength-accessories', 'unilateral alternating sets then bilateral drop set to correct a calf imbalance', 'To address a known left/right calf strength and size imbalance, Sam Sulek alternates single-leg calf raises (a handful of reps on each leg in turn) to near-fatigue, then finishes with a bilateral drop set to failure, using this specifically as a correction for asymmetry rather than as his default calf protocol.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 108 - Forearms and Calves - Work a Muscle To Grow a Muscle'),
('clinical', 'caution on breath-holding/bracing during isolation ''pump'' work', 'Sam Sulek notes that holding one''s breath and bracing hard to make veins and muscle stand out (e.g. for a flex or a heavy brace) can cause lightheadedness, comparing it to the hard brace used in a heavy deadlift, and cautions against doing it carelessly given the risk of feeling faint.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 108 - Forearms and Calves - Work a Muscle To Grow a Muscle'),
('volume-per-muscle', 'heavy weighted ab training over bodyweight endurance work, timed to diet phase', 'For ab hypertrophy Sam Sulek favors heavy, weighted, moderate-rep training (loaded cable or machine crunches taken to a burning near-failure point) over high-rep bodyweight endurance work like planks or toe touches, applying the same progressive-overload logic he uses for any other muscle; he trains abs directly mainly while cutting/dieting, not while bulking, since his ab development is already sufficient when bulking.', 'opinion', 'weak', NULL, '{"sets": "7-8", "reps": "around 20", "frequency_note": "recommends 2x/week if adding fresh ab work; done mainly during cutting phases"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 108 - Forearms and Calves - Work a Muscle To Grow a Muscle'),
('equipment', 'direct loaded neck training over a neck-harness attachment', 'To add neck thickness, Sam Sulek recommends direct loaded neck work done with basic equipment (lying on a bench holding a dumbbell against the forehead for neck-flexion curls, or lying sideways with a lighter dumbbell or plate for lateral neck curls) rather than a dedicated cable neck-harness attachment, which he considers unnecessarily elaborate though not ineffective.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 108 - Forearms and Calves - Work a Muscle To Grow a Muscle'),
('strength-accessories', 'grip width and elbow path on reverse-grip rows', 'Chris Bumstead stresses that hand width matters on reverse-grip rows: too narrow a grip causes the elbows to flare out, too wide a grip stresses the elbows; he aims for a grip wide enough that the elbows can track straight back close to the body, with full shoulder protraction on the stretch and full retraction at the top for maximum range of motion.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — FULL BACK WORKOUT | HOW TO BE A THAVAGE'),
('equipment', 'setting machine seat/arm position for full range of motion on a chest-supported row', 'On a chest-supported/low-row machine Chris Bumstead deliberately sets the seat as far back as possible, so the handles are hard to reach at the very start of the rep, in order to get a fuller range of motion; he notes that lifters with long arms often leave the machine set too close, which clips part of the rep at the top or bottom.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — FULL BACK WORKOUT | HOW TO BE A THAVAGE'),
('progression', 'double progression: adding reps before adding load', 'Chris Bumstead tracks his working weights per exercise and progresses primarily by adding reps at a given weight before adding load, e.g. targeting a higher rep count at the same leg-press weight (14 reps up to a goal of 18) before adding a plate, and only bumping dumbbell weight (e.g. 100lb to 105-110lb) once a rep target on a lift is met; he applies this to essentially one primary lift per movement pattern per session.', 'practice', 'weak', NULL, '{"example_leg_press": "4 plates for 14 reps, targeting 18 reps before adding a plate", "example_shoulder_press": "100lb dumbbells x12 x2 sets, targeting 105-110lb next"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — FULL BACK WORKOUT | HOW TO BE A THAVAGE'),
('volume-per-muscle', 'minimal working sets on a lighter/technique-focused back day', 'On a lighter, form-focused back session, Chris Bumstead deliberately limits himself to about two hard working sets per exercise (plus one lighter warm-up-style set) before moving to the next movement, prioritizing form and mind-muscle squeeze over total volume that day.', 'practice', 'weak', NULL, '{"working_sets": 2, "note": "plus one lighter set; described as a deliberately low-volume, technique-focused session"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — FULL BACK WORKOUT | HOW TO BE A THAVAGE'),
('volume', 'training through residual soreness with reduced intensity rather than skipping', 'Despite being very sore from a hard chest session three to four days earlier, Chris Bumstead trains again rather than taking a rest day, framing it as pushing through recovery at reduced intensity rather than skipping the session outright.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — FULL BACK WORKOUT | HOW TO BE A THAVAGE'),
('tempo', 'submaximal speed-work sets for rate-of-force development', 'Chris Bumstead incorporates deliberately submaximal, high-velocity work (a band-resisted bench press and a dumbbell speed press) using roughly 40-60% of his estimated one-rep max, moved as explosively as possible, explicitly to train rate of force production, contrasting the typically slow force output of a bodybuilder with the explosiveness of an athlete, while reducing joint and nervous-system stress compared to heavy grinding sets.', 'practice', 'weak', NULL, '{"load_pct_1rm": "40-60", "note": "5-8 reps per set, moved maximally fast; unstable banded-bar implement used partly for stability training"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — GYM RANT | Chest & Back Workout'),
('strength-accessories', 'explosive/ballistic warm-up before heavy pressing', 'Chris Bumstead warms up with explosive plyometric push-offs from the bench followed by a medicine-ball throw before heavy pressing work, describing the goal as building motor patterns for fast, explosive muscle-fiber recruitment that he isn''t naturally used to as a bodybuilder.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — GYM RANT | Chest & Back Workout'),
('guideline', 'relative-strength ratios used as an injury-proofing heuristic', 'Chris Bumstead and his training staff use a rule of thumb that accessory or secondary lifts should reach set percentages of a main lift to be considered injury-resistant, e.g. dip load should reach roughly 96% of bench press, a weighted pull-up about 45%, and a dumbbell external rotation about 4%, and that hitting these ratios across many joints and movements meaningfully lowers injury risk. No study or source is cited for these figures; this is an unverified practitioner heuristic rather than an established evidence-based standard, and is worth noting precisely because of that gap.', 'opinion', 'weak', NULL, '{"dip_pct_of_bench": 96, "pullup_pct_of_bench": 45, "external_rotation_pct_of_bench": 4}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — GYM RANT | Chest & Back Workout'),
('clinical', 'post-shoulder-injury external rotation rehab progression', 'Following a shoulder tear and a stem-cell injection roughly seven months earlier, Chris Bumstead progressed external rotation work from literally zero added weight (lying on his side moving only a fat-grip attachment) back up to hitting new external-rotation personal records, describing this slow accessory-lift progression as central to his return from the injury.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — GYM RANT | Chest & Back Workout'),
('volume-per-muscle', 'higher set count when first learning a new movement pattern', 'For movements new to his programming, Chris Bumstead deliberately runs more working sets than usual (five, versus his more typical two to three), reasoning that more repetitions of a new motor pattern speeds up motor learning, independent of any hypertrophy consideration.', 'opinion', 'weak', NULL, '{"sets": 5, "typical_sets": "2-3"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — GYM RANT | Chest & Back Workout'),
('volume-per-muscle', 'per-muscle training frequency tolerance differs even within the same leg session', 'Sam Sulek can train hamstrings twice a week but cannot train quads twice a week: heavy quad work (leg press plus a secondary press plus leg extensions to failure) leaves about three days of residual soreness and reduced output, while his hamstrings recover fast enough to tolerate higher frequency.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Quads Hams Adductors and Calves - Bulk Day 21'),
('volume-per-muscle', 'cutting planned sets when a muscle is already pre-fatigued by an earlier exercise', 'Sam Sulek''s default is roughly eight working sets per muscle group, but when a secondary muscle (e.g. hamstrings) is already partly fatigued by an earlier compound movement for a different target muscle (e.g. leg press for quads), he cuts that muscle''s sets roughly in half once it hits a subjective ''feeling of completion,'' rather than forcing the full set count.', 'practice', 'weak', NULL, '{"baseline_sets_per_muscle": 8, "reduced_sets_when_prefatigued": 4}'::jsonb, 'Sam Sulek (high-volume physique training) — Quads Hams Adductors and Calves - Bulk Day 21'),
('guideline', 'session duration is not a valid proxy for training intensity', 'Sam Sulek explicitly rejects two opposing gym claims that use the same logic: that a leg day must finish inside 45 minutes to count as sufficiently intense, and conversely that it must last two-plus hours to be serious, calling both versions bro-science and noting that the same underlying logic gets used to argue opposite conclusions.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Quads Hams Adductors and Calves - Bulk Day 21'),
('strength-accessories', 'direct adductor work as injury-proofing for heavy or unstable squats/presses', 'Sam Sulek treats the adductors as a stabilizer muscle worth training directly rather than only via presses and squats, noting that instability under heavy load (Smith squats, pendulum squats) can tweak an undertrained adductor, and that direct adductor work should be eased into if it hasn''t been trained in months since it can produce severe soreness very quickly in an unaccustomed lifter.', 'practice', 'weak', NULL, '{"note": "roughly 10 sets in his own adductor session; reports extreme, sleep-disrupting soreness after months without direct adductor work"}'::jsonb, 'Sam Sulek (high-volume physique training) — Quads Hams Adductors and Calves - Bulk Day 21'),
('strength-accessories', 'direct hip flexor training as an aesthetic technique for quad-line thickness', 'Sam Sulek relays a peer''s tip that training hip flexors directly (e.g. a hip-flexor machine performing a knee raise against a pad) visibly thickens the quad line up to the top of the leg in a standing front pose; an exercise-selection idea he had not previously used but was considering adding based on that anecdote alone.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Quads Hams Adductors and Calves - Bulk Day 21'),
('periodization', 'rotating which body part carries the ''heavy'' day across the training week', 'After stacking four consecutive maximally heavy training days across different body parts (arms, back, chest, then legs) and feeling unusually beat up, Sam Sulek concludes he should alternate heavy/light designation not just by day but by body part, e.g. pairing a heavy leg day with a lighter chest day and a heavy back day with a lighter arm day, so heavy stimulus is spread more evenly across the week instead of compounding.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Quads Hams Adductors and Calves - Bulk Day 21'),
('volume', 'flexing/squeezing the target muscle as a local readiness check', 'Before deciding how hard to train a muscle, Sam Sulek flexes and squeezes it hard as a quick readiness test: if it squeezes fully without feeling tender, he considers it ready to train hard; if it feels tender or blunted, he treats that as a signal to hold back on intensity for that muscle that day.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Quads Hams Adductors and Calves - Bulk Day 21'),
('volume', 'grip-strength squeeze as a systemic fatigue/readiness check', 'Sam Sulek uses maximal hand-grip force, checked without a dynamometer by simply making as hard a fist as possible, as a rough gauge of whole-body systemic fatigue distinct from local muscle soreness; he reports a noticeably weaker squeeze on poorly-slept, dehydrated, or under-fed days, and uses this to decide whether to push for a heavy or PR-attempt session or scale back that day, describing it as a better decision rule than guessing. He credits the idea to another lifter rather than claiming it as his own.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Quads Hams Adductors and Calves - Bulk Day 21'),
('progression', 'repeated-bout adaptation distinguishes early-block soreness from overtraining', 'Sam Sulek argues that a lifter feeling wrecked after a first exposure to a hard multi-day training block is not overtrained, just unadapted to that intensity, and that the same block repeated after a short break is tolerated much better on the second and third exposure; he applies this to his own return from six months of light ''maintenance'' prep training to heavier set-based training, expecting to need a short readjustment window (extra rest, lighter squeezing days) rather than treating the soreness itself as a red flag.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Quads Hams Adductors and Calves - Bulk Day 21'),
('strength-accessories', 'light strict unilateral squeeze sets progressing to heavier bilateral bounce sets for calves', 'Sam Sulek''s calf-training pattern starts with light, strict, single-leg seated calf raises for moderate-high reps emphasizing a full squeeze, then progresses to heavier double-leg sets with a bit more bounce and momentum to finish the muscle group.', 'practice', 'weak', NULL, '{"unilateral_phase": "1 plate, 15 reps per side, repeated for several rounds, strict squeeze", "bilateral_phase": "3 plates, 20 reps, more bounce/momentum"}'::jsonb, 'Sam Sulek (high-volume physique training) — Quads Hams Adductors and Calves - Bulk Day 21'),
('volume-per-muscle', 'ascending-weight, descending-rep pyramid to add extra volume before the top set', 'For lateral raises, Chris Bumstead and his coach run an ascending-weight, descending-rep pyramid, starting well below his normal 10-12 rep working weight and increasing weight each set as reps fall, before arriving at the actual heavy working set, used deliberately to add extra volume rather than as ordinary warm-up sets.', 'practice', 'weak', NULL, '{"start_weight_lb": 26, "start_reps": 20, "normal_working_weight_lb": "35-40", "normal_working_reps": "10-12"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Shoulders and Arms Donut Pump'),
('strength-accessories', 'lateral raise range-of-motion cue tied to trap recruitment', 'Coaching cue used with Chris Bumstead on standing lateral raises: extend the range of motion by letting the dumbbells continue slightly in front of the thighs on the descent rather than stopping at the thighs, for more delt stretch, but the moment traps or lower back start doing the work (felt as the raise turning into a shrug-like pull) is the signal to shorten the range back up; the goal is delt tension without trap or low-back involvement.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Shoulders and Arms Donut Pump'),
('clinical', 'live pain-guided exercise and angle selection around a chronically irritated shoulder', 'Chris Bumstead trains through joint tightness but avoids ranges that produce actual joint pain, live-switching exercise angle or machine mid-session based on real-time pain feedback, e.g. abandoning a stretch-position variation because it ''came off the delt completely'' when adjusted to avoid pain; some exercises (e.g. machine shoulder press) are reported as consistently pain-free while others (leaning cable or dumbbell laterals) are pain-free only with strict form and become painful once form breaks down.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Shoulders and Arms Donut Pump'),
('strength-accessories', 'contradiction: testing multiple exercise variations to find what an individual lifter feels, against a universal ''stretch position is best'' rule', 'Chris Bumstead''s coach ran him through several curl variations in one session (a stretch-emphasis position, an upright version, and a mid-range roughly 120-degree version) specifically to find which one this individual lifter felt best in, and stated explicitly that a stretch-emphasis position being the best variation is not universal: a lifter with tight shoulders or elbows may do better on a different variation. Current hypertrophy research generally favors lengthened/stretch-position partial training as superior on average for muscle growth; this practitioner instead treats the best variation as individual-dependent based on joint comfort, not a fixed rule to apply to everyone.', 'opinion', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Shoulders and Arms Donut Pump'),
('volume', 'pump quality tracks sleep/systemic recovery more than food intake', 'Chris Bumstead reports that when he is a little overtrained or underslept he fails to get a strong pump regardless of how much he eats, describing the sensation as glycogen-full but nervous-system depleted, and uses pump quality as a felt indicator of systemic recovery state distinct from local muscle soreness.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Shoulders and Arms Donut Pump'),
('periodization', 'four-day full-body rotation with an active-recovery rest day', 'Chris Bumstead''s default training pattern covers all body parts across four training days before taking a rest day, and that rest day is used for active recovery (massage therapy, sauna, light stretching/cardio) rather than complete inactivity; on the occasion described he pushed a fifth consecutive training day due to travel logistics, which he notes is not his normal routine.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Shoulders and Arms Donut Pump'),
('clinical', 'accumulated joint microtrauma reported after a long heavy-training career', 'An ultrasound of Chris Bumstead''s shoulders and knees reportedly showed extensive micro-tears throughout the joints despite his being fully functional day to day; he and his team frame this as a normal consequence of many years of heavy bodybuilding training. This is an anecdotal data point on long-term joint wear in veteran heavy lifters, not evidence about the safety of any specific protocol.', 'opinion', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Shoulders and Arms Donut Pump'),
('strength-accessories', 'consensus anchor lifts for a hypertrophy program', 'Greg Doucette agrees that a squat variation, a deadlift variation, a bench press variation, a pull-up/lat-pulldown variation, an overhead press variation, a standing barbell curl, and a bent-over row variation should anchor any hypertrophy-focused program, substituting an easier variation (trap-bar or sumo deadlift, incline or dumbbell bench, assisted pull-up or lat pulldown, seated or standing dumbbell overhead press) when injury or equipment prevents the standard version.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Top 12 Exercises To Maximize Muscle Growth'),
('strength-accessories', 'rotator cuff and corrective exercises are for injury prevention, not a hypertrophy priority', 'Greg Doucette agrees that external-rotation rotator-cuff work and face pulls are valuable exercises but explicitly excludes them from his top-12 muscle-building list, arguing they don''t build much muscle mass even though they are good corrective/prehab tools, drawing a distinction between injury-prevention exercise selection and hypertrophy-driven exercise selection.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Top 12 Exercises To Maximize Muscle Growth'),
('strength-accessories', 'loaded press variation preferred over bodyweight push-ups for hypertrophy', 'Greg Doucette prefers a loaded chest press variation (incline barbell/dumbbell bench, or a converging-path chest machine) over the standard push-up for hypertrophy, reasoning that a trained lifter can perform hundreds of unloaded push-ups, meaning the exercise runs out of usable external loading for that lifter''s strength level.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Top 12 Exercises To Maximize Muscle Growth'),
('volume-per-muscle', 'calves are commonly omitted from generic ''must-do'' exercise lists but shouldn''t be skipped', 'Greg Doucette calls out that a well-known trainer''s top-12 muscle-building exercise list contained zero calf exercises, and argues calves shouldn''t be neglected even for a physique competitor since they remain visible in shorts; he names the donkey calf raise as his preferred direct calf exercise.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Top 12 Exercises To Maximize Muscle Growth'),
('volume-per-muscle', 'lateral delt prioritized over direct front-delt work for physique width', 'Greg Doucette does side lateral raises every single shoulder session and considers side-delt development the single most impactful factor for perceived physique width, but deliberately skips dedicated front-delt work such as front raises, reasoning that bench press and overhead press already provide sufficient front-delt stimulus; he prefers a reverse pec-deck movement over face pulls for direct rear-delt work.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Top 12 Exercises To Maximize Muscle Growth'),
('strength-accessories', 'picking the more compound or more difficult option for a lagging muscle group', 'Greg Doucette prefers leg press (more compound, heavier loading) over leg extensions when quads are the lagging area, and prefers the glute-ham raise over machine hamstring curls when hamstrings are lagging, describing the glute-ham raise as the more difficult and more effective of the two for producing a hamstring training effect.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Top 12 Exercises To Maximize Muscle Growth'),
('tempo', 'deliberate cheat curls used as an overload technique for biceps', 'Greg Doucette endorses standing barbell curls performed with some intentional cheating or body momentum specifically because it allows heavier loads than strict form would permit, treating this as a legitimate overload technique for biceps rather than a form fault to eliminate.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Top 12 Exercises To Maximize Muscle Growth'),
('tempo', 'eccentric time-under-tension framed as the biggest low-hanging-fruit lever for hypertrophy', 'In direct conversation with his coach, Chris Bumstead agrees that emphasizing time under tension on the eccentric portion of a lift is the single biggest low-hanging-fruit lever for most people''s hypertrophy training, reasoning that the eccentric produces more muscle damage and that eccentric-focused training is also one of the fastest ways to build strength, which in turn supports further hypertrophy.', 'opinion', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Delts Workout'),
('strength-accessories', 'scapular retraction and sternum position as the cue that determines row target (lats vs. mid-back)', 'Chris Bumstead''s coach cues him that a row only produces mid-back thickness if it includes deliberate scapular retraction/depression with the sternum kept up; without that extra shortening at the top of the rep, the row mainly recruits and builds lat width instead, which is framed as relevant specifically because CBum''s mid-back is a comparative weak point next to his lat width.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Delts Workout'),
('clinical', 'live pain-rating protocol used to select load and movement around a shoulder issue', 'Chris Bumstead''s coach runs a live pain assessment before loading a shoulder-affected movement: asking for a 0-10 pain rating, testing different arm positions and hand positions, comparing left vs. right, and adjusting exercise choice and load in real time based on the feedback, rather than following a fixed pre-set program.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Delts Workout'),
('volume-per-muscle', 'straight sets followed by a rest-pause finisher to extend a set''s stimulus', 'Chris Bumstead''s coach programs a scheme of a few straight sets followed by a rest-pause finisher (taken to failure, a short rest, then continuing) when the muscle is still able to produce more stimulus, deciding on the spot whether the rest-pause is needed based on how quickly the preceding sets ''knocked out.''', 'practice', 'weak', NULL, '{"rest_pause_interval_sec": 15}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Delts Workout'),
('tempo', 'higher rep range with controlled tempo chosen to protect an injured shoulder while still training hard', 'For an Arnold press variation, Chris Bumstead''s coach deliberately targets a higher rep range (12-15) with a more controlled tempo specifically because the shoulder responds better to higher reps and because they want to leave intensity in reserve for a later phase of contest prep, using rep range and tempo together as a joint-protective substitute for simply going heavier.', 'practice', 'weak', NULL, '{"rep_range": "12-15"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Delts Workout'),
('strength-accessories', 'incline bench positioning used to reduce trap dominance on lateral raises', 'Chris Bumstead''s coach has him try lateral raises on a slight incline bench as a variation specifically intended to take the traps out of the movement (at the cost of requiring more of a stretch position), used as a targeting tool when trap involvement is hard to avoid on a standing or standard lateral raise.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Delts Workout'),
('periodization', 'varying exercise/loading scheme across sessions to manage cumulative fatigue rather than always adding volume', 'Chris Bumstead''s coach describes a deliberate philosophy of finding different methods and loading variables to reproduce the same training stimulus with less cumulative fatigue, rather than treating total sets and reps as the only lever, explicitly framing this as not being ''a victim to how many sets and reps you can do.''', 'opinion', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Delts Workout'),
('progression', 'targeting small week-to-week load increases, tracked systematically with coach review', 'Chris Bumstead''s coach targets roughly a 5-10% load increase week to week on a given exercise (e.g. moving from three plates to three plates plus a five-pound plate) rather than large jumps, and tracks loads systematically (via a training app or photos of the top set) with regular review between athlete and coach to fine-tune progression rather than progressing by feel alone.', 'practice', 'weak', NULL, '{"target_increment_pct": "5-10", "example": "three plates (about 25lb aside) moving to three plates plus a 5lb plate"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Delts Workout'),
('clinical', 'keeping cold exposure away from training sessions to avoid blunting hypertrophy signaling', 'Chris Bumstead and his coach avoid cold plunge/cryotherapy close to training sessions, citing a cited-but-unsourced study (the coach recalls it as roughly 2018-2019) suggesting cold exposure soon after resistance training blunts the inflammatory signaling needed for muscle growth even though strength gains are less affected; they instead use sauna (particularly far-infrared) after training for recovery, but only once heart rate has settled toward a parasympathetic state rather than immediately post-workout.', 'practice', 'weak', NULL, '{"note": "cold exposure kept far in time from training; sauna used post-training after a deliberate parasympathetic down-shift"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — Back and Delts Workout'),
('strength-accessories', 'chest exercise cue — bench-supported cross-body cable press', 'Sulek used a bench-supported, semi cross-body cable press (built by combining individual cable stations rather than a dedicated machine) as a chest starter, describing it as very squeeze-focused and highly recommending the setup.', 'practice', 'weak', NULL, '{"note": "several sets, described only qualitatively"}'::jsonb, 'SamSulek / Sam Sulek (high-volume physique training) — 9 Days To Run It Back - Chest at The Pro''s Gym Columbus'),
('volume-per-muscle', 'quad training ratio shift toward pressing', 'Sulek changed his quad training ratio over an off-season from roughly 25 percent pressing / 75 percent leg extension work to about 75 percent pressing / 25 percent leg extension, and reports the change added noticeable thickness to his quads; his prior pattern had been one or two maximal squat sets followed almost entirely by leg extension volume.', 'practice', 'weak', NULL, '{"old_press_pct": 25, "old_extension_pct": 75, "new_press_pct": 75, "new_extension_pct": 25}'::jsonb, 'SamSulek / Sam Sulek (high-volume physique training) — 9 Days To Run It Back - Chest at The Pro''s Gym Columbus'),
('equipment', 'preference for ascending strength-curve leg press machines', 'Sulek prefers leg press or pendulum-style machines with an ascending (increasing) strength curve — lighter at the bottom of the rep, heavier at the top — over a linear sled leg press or free-bar squat/hack squat, because it lets him load more total pressing weight while still getting a solid stretch at the bottom of the range of motion.', 'opinion', 'weak', NULL, NULL, 'SamSulek / Sam Sulek (high-volume physique training) — 9 Days To Run It Back - Chest at The Pro''s Gym Columbus'),
('periodization', 'pre-competition training taper', 'Sulek stops hard lifting about two to three days before a bodybuilding show (e.g. last heavy training day on Tuesday for a Friday show), reasoning that no meaningful muscle growth occurs during the final deep-deficit days so there is little point continuing to train hard that close to stepping on stage.', 'practice', 'weak', NULL, '{"note": "roughly 2-3 rest/no-lift days before competition day"}'::jsonb, 'SamSulek / Sam Sulek (high-volume physique training) — 9 Days To Run It Back - Chest at The Pro''s Gym Columbus'),
('progression', 'gradual reintroduction of heavy loads after a diet phase', 'Sulek describes deliberately re-introducing heavy pressing loads gradually after finishing a competition diet, rather than immediately loading back up to pre-diet weights, citing the risk of tendon/muscle injury (specifically pec tears off heavy incline Smith machine pressing) if maximal loads are attempted before strength and connective tissue capacity have rebuilt.', 'practice', 'weak', NULL, NULL, 'SamSulek / Sam Sulek (high-volume physique training) — 9 Days To Run It Back - Chest at The Pro''s Gym Columbus'),
('volume-per-muscle', 'commonly under-trained muscle groups', 'Sulek names calves, hamstrings, forearms, and rear delts as the muscle groups most commonly neglected in typical training programs.', 'opinion', 'weak', NULL, NULL, 'SamSulek / Sam Sulek (high-volume physique training) — The Bulk Day 10 - Forearms and Calves'),
('strength-accessories', 'forearm thickness requires direct wrist flexion and extension work', 'Sulek argues that indirect forearm work such as hammer curls or reverse curls trains the brachioradialis (which affects the upper-forearm/elbow taper) but does not build forearm “thickness”; thickness instead comes from direct wrist flexion work (e.g. dumbbell wrist curls hanging the forearm off a bench, or cable wrist curls) and direct wrist extension work (light-weight reverse wrist curls), both trained explicitly rather than as a byproduct of curls or rows.', 'opinion', 'weak', NULL, NULL, 'SamSulek / Sam Sulek (high-volume physique training) — The Bulk Day 10 - Forearms and Calves'),
('strength-accessories', 'wrist straps reduce forearm stimulus from back and curl work', 'Sulek reports using wrist straps on back exercises and even on dumbbell curls, which removes grip demand and means his forearms get little indirect stimulus from those lifts, requiring dedicated direct forearm work instead.', 'practice', 'weak', NULL, NULL, 'SamSulek / Sam Sulek (high-volume physique training) — The Bulk Day 10 - Forearms and Calves'),
('strength-accessories', 'very light load needed for wrist extensor training', 'Sulek trains wrist extensors (reverse wrist curls) with very light load — around 15-20 lb dumbbell, sometimes as low as 10 lb — because he considers the extensors far weaker than the flexors and says even a 5 lb dumbbell could produce a good burnout set, in contrast to the much heavier load used for wrist flexion work.', 'practice', 'weak', NULL, '{"extensor_load_lb_low": 10, "extensor_load_lb_high": 20, "flexor_load_lb": 60}'::jsonb, 'SamSulek / Sam Sulek (high-volume physique training) — The Bulk Day 10 - Forearms and Calves'),
('strength-accessories', 'unilateral calf training to correct a side-to-side imbalance', 'Sulek trains calves unilaterally when he notices a strength/size imbalance, deliberately capping the stronger leg''s rep count at whatever rep the weaker leg reaches failure (e.g. stopping the right calf at 20 reps even though it could do 25, matching the weaker left calf''s 20-rep failure point) so the weaker side gets proportionally more stimulus over time and the sides even out.', 'practice', 'weak', NULL, '{"note": "example: weak side failure at 20 reps, strong side capped at same 20 reps rather than its own ~25-rep capacity"}'::jsonb, 'SamSulek / Sam Sulek (high-volume physique training) — The Bulk Day 10 - Forearms and Calves'),
('tempo', 'varying rep style between calf exercises in the same session', 'Sulek uses deliberately different execution styles across calf exercises in one session — slow, controlled reps on a seated/leg-press-based calf raise aimed at squeeze, versus heavier, more “brutish” loaded reps (without bouncing) on a second calf movement aimed at overload rather than squeeze.', 'practice', 'weak', NULL, NULL, 'SamSulek / Sam Sulek (high-volume physique training) — The Bulk Day 10 - Forearms and Calves'),
('guideline', 'distinguishing normal tiredness from training fatigue when deciding on rest days', 'Sulek describes taking rest days only when he judges himself genuinely fatigued from training (not merely sleepy or tired from being on his feet), training on a near-daily basis otherwise; he also notes beginners typically need longer recovery windows between sessions than experienced lifters training the same muscle.', 'opinion', 'weak', NULL, NULL, 'SamSulek / Sam Sulek (high-volume physique training) — The Bulk Day 10 - Forearms and Calves'),
('volume-per-muscle', 'antagonist tricep/bicep superset structure to preserve pump', 'On arm day, Sulek alternates two sets of a triceps movement with two sets of a biceps movement back and forth (rather than blocking all triceps then all biceps), reasoning that “the pump is fleeting” and he wants both muscles fully pumped together for a finishing pose-check.', 'practice', 'weak', NULL, '{"note": "alternating 2-set blocks, tricep-bicep-tricep-bicep pattern"}'::jsonb, 'SamSulek / Sam Sulek (high-volume physique training) — Winter Shredathon Day 101 - Arms You Glad It''s Not Legs'),
('volume-per-muscle', 'reduced per-muscle set totals for arms while dieting', 'Sulek describes an arm session totaling six triceps sets and five biceps sets as “a little lower volume” than his normal arm-day approach, targeting roughly five to seven working sets per muscle in that session.', 'practice', 'weak', NULL, '{"triceps_sets": 6, "biceps_sets": 5, "target_range_low": 5, "target_range_high": 7}'::jsonb, 'SamSulek / Sam Sulek (high-volume physique training) — Winter Shredathon Day 101 - Arms You Glad It''s Not Legs'),
('tempo', 'controlled reps on triceps pushdowns to avoid injury risk', 'Sulek deliberately keeps triceps pushdown/extension reps controlled rather than bouncy, saying uncontrolled reps on that movement are “asking for trouble.”', 'opinion', 'weak', NULL, NULL, 'SamSulek / Sam Sulek (high-volume physique training) — Winter Shredathon Day 101 - Arms You Glad It''s Not Legs'),
('volume', 'contradiction: training effort claimed to outweigh prescribed volume/RIR', 'Sulek argues that the specific programming variable chosen (reps in reserve, rep range, high vs low volume/frequency) matters far less than how hard the lifter trains and wants results, asserting that a lifter training with roughly half the sets but going closer to failure and with more desire will out-perform a lifter doing double the volume at a lighter effort level even if total workload is matched. This conflicts with resistance-training literature showing a fairly consistent volume dose-response relationship (more weekly hard sets per muscle producing more hypertrophy) that holds up across lifters regardless of subjective drive, so it is recorded here as a contradiction between elite-practice framing and the literature rather than being promoted.', 'opinion', 'weak', NULL, NULL, 'SamSulek / Sam Sulek (high-volume physique training) — Winter Shredathon Day 104 - Back - Hefty Sets'),
('volume', 'rest periods scaled to load/muscle rather than fixed', 'Sulek varies rest between working sets by how taxing the movement is rather than using a fixed timer: about 1 to 1.5 minutes between same-machine sets on a normal lift, up to 2.5 minutes for regular working sets, and up to 5 minutes between heavy CNS-taxing compound sets like squats or heavy presses; his cue to start the next set is feeling recovered enough (“caught your breath”) rather than a clock.', 'practice', 'weak', NULL, '{"same_machine_rest_min": 1, "same_machine_rest_max_min": 1.5, "normal_set_rest_max_min": 2.5, "heavy_compound_rest_max_min": 5}'::jsonb, 'SamSulek / Sam Sulek (high-volume physique training) — Winter Shredathon Day 104 - Back - Hefty Sets'),
('tempo', 'fast/heavy sets early, slower controlled sets later, on the same exercise', 'On back day, Sulek''s first pulldown sets are fast and heavy with no slow eccentric (“nothing fancy, no 5-second eccentric”) to maximize effort and stimulation, followed later in the session by slower, more controlled sets of similar movements.', 'practice', 'weak', NULL, NULL, 'SamSulek / Sam Sulek (high-volume physique training) — Winter Shredathon Day 104 - Back - Hefty Sets'),
('strength-accessories', 'stretch-to-squeeze cue on a pulldown-style back finisher', 'On a pulldown-style back finisher done with a straight/easy bar instead of his usual long D-handles, Sulek cues himself for a big lat stretch at the top of the rep and a full mid-trap squeeze at the bottom as he leans back into the flexed position.', 'practice', 'weak', NULL, NULL, 'SamSulek / Sam Sulek (high-volume physique training) — Winter Shredathon Day 104 - Back - Hefty Sets'),
('volume', 'cutting back concurrent cardio volume after noticing accumulating fatigue', 'After suspecting he was pushing into overreaching from doing roughly an hour of cardio both in the morning and again immediately post-lift, Sulek reduced his post-workout cardio from 60 to 30 minutes and eliminated post-workout cardio specifically after leg day, judging leg-day-plus-full-cardio the biggest contributor to his perceived fatigue.', 'practice', 'weak', NULL, '{"pre_change_post_workout_cardio_min": 60, "post_change_post_workout_cardio_min": 30}'::jsonb, 'SamSulek / Sam Sulek (high-volume physique training) — Winter Shredathon Day 104 - Back - Hefty Sets'),
('strength-accessories', 'chest session exercise order — heavy press, controlled press, stretch-focused isolation', 'Sulek''s chest sessions move from an initial heavy, relatively fast-rep pressing movement (Smith machine or similar) to fatigue the chest and start a pump, into a second pressing movement done slower with more emphasis on the top-of-rep squeeze, finishing with lighter cable flies or pec deck work for stretch and burnout.', 'practice', 'weak', NULL, '{"note": "roughly 7-8 total pressing-type sets before finishing with flye/pec-deck work in this session"}'::jsonb, 'SamSulek / Sam Sulek (high-volume physique training) — Fall Cut Day 19 - Chest and Shoulders Home Gym'),
('strength-accessories', 'incline pressing prioritized because upper chest is commonly neglected', 'Sulek prioritizes incline pressing movements for chest, reasoning that the upper chest is typically neglected in most lifters'' training and that a fuller upper chest makes the whole chest look bigger.', 'opinion', 'weak', NULL, NULL, 'SamSulek / Sam Sulek (high-volume physique training) — Fall Cut Day 19 - Chest and Shoulders Home Gym'),
('smith', 'Smith machine chosen as the starting movement because it can be loaded far beyond capacity', 'Sulek intentionally starts a chest session on the Smith machine because, unlike a stack-loaded machine such as a pec deck, it can be loaded essentially without limit, letting him push a true 8-12 rep near-failure heavy set without capping out on the available weight; he says he wishes more stack machines (citing leg extension as an example) had that much headroom too.', 'opinion', 'weak', NULL, '{"target_rep_range_low": 8, "target_rep_range_high": 12}'::jsonb, 'SamSulek / Sam Sulek (high-volume physique training) — Fall Cut Day 19 - Chest and Shoulders Home Gym'),
('volume-per-muscle', 'default per-muscle working-set counts, adjusted for diet phase', 'Sulek reports a personal default of about 11 working sets per muscle group most days but 8 sets specifically for shoulders (a habit he calls “arbitrary” but within his own recommended range); while cutting he dropped this to 8 sets per muscle group across the board, and was considering going as low as 6 sets per muscle group during a bulk phase.', 'practice', 'weak', NULL, '{"default_sets_most_muscles": 11, "default_sets_shoulders": 8, "cut_phase_sets": 8, "bulk_phase_low_end_sets": 6}'::jsonb, 'SamSulek / Sam Sulek (high-volume physique training) — Fall Cut Day 19 - Chest and Shoulders Home Gym'),
('volume', 'rest periods much shorter for small isolation movements than heavy compounds', 'Sulek rests only about 30-45 seconds between rear-delt/side-delt lateral raise sets, versus roughly 2+ minutes after a heavy bench-type set, reasoning that the smaller isolation movements do not create as much systemic fatigue.', 'practice', 'weak', NULL, '{"isolation_rest_sec_low": 30, "isolation_rest_sec_high": 45, "heavy_compound_rest_min": 2}'::jsonb, 'SamSulek / Sam Sulek (high-volume physique training) — Fall Cut Day 19 - Chest and Shoulders Home Gym'),
('strength-accessories', 'rear delts trained first in a shoulder session, before side delts', 'Sulek trains rear delts before side delts within a shoulder session so the workout finishes on a side-delt pump, and considers well-developed rear delts important for a rounded 3D shoulder look from the side and back (versus the front and side delts, which are visible even without direct rear-delt work).', 'opinion', 'weak', NULL, NULL, 'SamSulek / Sam Sulek (high-volume physique training) — Fall Cut Day 19 - Chest and Shoulders Home Gym'),
('strength-accessories', 'deliberately rotating movement variations even for the same muscle', 'Sulek deliberately varies which specific exercise variation he uses for a given muscle across sessions (e.g. different lateral raise or curl variations) rather than always repeating the identical movement, reasoning that different variations of an exercise stimulate the same muscle in slightly different ways.', 'opinion', 'weak', NULL, NULL, 'SamSulek / Sam Sulek (high-volume physique training) — Fall Cut Day 19 - Chest and Shoulders Home Gym'),
('volume-per-muscle', 'higher-rep, lighter-load approach for side/rear delts', 'For side and rear delt work Sulek deliberately avoids going too heavy, aiming to be able to do at least 15 reps and chasing a “burning” sensation rather than maximal load, saying he doesn''t think delts need much weight to grow — while noting himself that this reasoning might just be “bro science.”', 'opinion', 'weak', NULL, '{"min_target_reps": 15}'::jsonb, 'SamSulek / Sam Sulek (high-volume physique training) — Fall Cut Day 19 - Chest and Shoulders Home Gym'),
('progression', 'ramped warm-up sets before top working weight', 'Before working sets, Sulek performs a progressively-loaded warm-up ramp (e.g. a plate for about five reps, two plates for three reps, three plates for three reps) rather than jumping straight to top weight.', 'practice', 'weak', NULL, '{"note": "example ramp: 1 plate x5, 2 plates x3, 3 plates x3, before top working sets"}'::jsonb, 'SamSulek / Sam Sulek (high-volume physique training) — Fall Cut Day 19 - Chest and Shoulders Home Gym'),
('tempo', 'contradiction: squeeze-over-stretch emphasis in isolation work', 'Sam Sulek trains isolation lifts (tricep pushdowns, curls) to emphasize a hard, tight peak-contraction squeeze at the fully flexed position, explicitly pushing back on the "it''s all about the stretch" framing common in current content, arguing a rep needs a real squeeze as well as a real stretch to count as complete. This runs counter to the stretch-mediated-hypertrophy emphasis (deep stretch under load, lengthened partials) the corpus holds at higher confidence elsewhere.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 109 - Arms - Christmas Tree Coming Back'),
('strength-accessories', 'minimal exercise selection is sufficient for a complete session', 'Sam Sulek argues a workout doesn''t need many movements or angles to "count" — he describes an 8-hard-set chest day using only incline Smith machine press and cable flyes as complete, and recalls his early training years using only a barbell, rack, and dumbbells as fully sufficient for training every body part; results come from effort per set, not exercise variety.', 'practice', 'weak', NULL, '{"note": "example: 8 hard sets across 2 movements (incline Smith press + cable flyes) treated as a complete chest day"}'::jsonb, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 109 - Arms - Christmas Tree Coming Back'),
('strength-accessories', 'antagonist-pair supersetting on arm day', 'On arm day, Sam Sulek alternates triceps and biceps exercises back-to-back in pairs (tricep, bicep, tricep, bicep, tricep, bicep) rather than completing all triceps work before moving to biceps.', 'practice', 'weak', NULL, '{"note": "roughly 3 exercise pairs across an arm session"}'::jsonb, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 109 - Arms - Christmas Tree Coming Back'),
('strength-accessories', 'opens a session light and builds fatigue across reps rather than starting near-maximal', 'Sam Sulek deliberately starts the first working set of a session at a weight that is easy for the first several reps, explicitly aiming to maximize "fatigue per rep" accumulated across the set rather than picking a load that is already hard on rep one.', 'practice', 'weak', NULL, '{"note": "first ~5 reps described as easy at the chosen starting weight"}'::jsonb, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 109 - Arms - Christmas Tree Coming Back'),
('periodization', 'decides rest days on a plan, not on immediate post-workout fatigue', 'Sam Sulek deliberately avoids letting how exhausted he feels immediately after a hard session dictate whether tomorrow is a rest day, comparing that bias to grocery shopping while hungry; he waits to evaluate recovery need with a clearer head rather than deciding in the moment.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Winter Shredathon Day 109 - Arms - Christmas Tree Coming Back'),
('volume', 'contradiction: trains near failure by default, rejects reps-in-reserve as a routine approach', 'Sam Sulek says he "can''t sympathize with" reps-in-reserve training, specifically criticizing lifters who stop a set at mild discomfort and move on; he frames pushing sets hard, to true failure, as simply the correct way to train. This conflicts with RIR-based programming (leaving 1-3 reps in reserve on most sets) that the corpus generally supports for sustainable volume accumulation.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Spring Cut Day 24 - Back Calves and Post Workout Meal'),
('volume', 'autoregulates rest periods by felt readiness rather than a fixed clock', 'Sam Sulek rests between sets until he feels he can repeat roughly the same weight as the prior set (not necessarily the same rep count), rather than timing a fixed interval; he estimates this can be as short as about 45 seconds for a lighter/burn-oriented movement (side laterals) and as long as about 4 minutes for a heavy compound lift (squats).', 'practice', 'weak', NULL, '{"rest_seconds_min": 45, "rest_seconds_max": 240, "note": "rest until able to repeat roughly the same weight, not necessarily the same reps"}'::jsonb, 'Sam Sulek (high-volume physique training) — Spring Cut Day 24 - Back Calves and Post Workout Meal'),
('volume', 'caloric deficit shortens usable rest periods and per-set work capacity', 'Sam Sulek reports that when dieting (versus bulking/glycogen-full), he fatigues faster within a set, loses the pump faster between sets, and needs less rest before feeling ready for the next set — attributing this to doing less total work per set while dieted, not to faster true recovery. He cites two heavy chest-press sets leaving him unusually "cooked" while cutting.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Spring Cut Day 24 - Back Calves and Post Workout Meal'),
('strength-accessories', 'matches reps on the stronger side to the weaker side on unilateral work', 'For a visibly smaller/weaker side (e.g., one calf), Sam Sulek trains that side to failure first, then caps the stronger side''s set at the same rep count rather than letting it go further, applying this rule on any single-arm or single-leg movement to reduce left/right asymmetry over time.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Spring Cut Day 24 - Back Calves and Post Workout Meal'),
('strength-accessories', 'hand/grip position on lat pulldown changes squeeze emphasis', 'Sam Sulek switches to a palm-only grip on a close/mag-style handle (instead of a full straight-bar grip with straps) specifically because the compromised grip lets him squeeze harder at the bottom of the pulldown, even though it forces him to use less weight — a deliberate trade of load for peak contraction.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Spring Cut Day 24 - Back Calves and Post Workout Meal'),
('strength-accessories', 'adjusts planned exercise order live based on in-session mind-muscle feel', 'After a warm-up set on a straight-bar lat pulldown, Sam Sulek noticed his lats weren''t "firing" as usual and abandoned it as the day''s starting movement, substituting lighter single-arm rows instead — treating exercise order as adjustable in real time based on activation feel rather than fixed in advance.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Spring Cut Day 24 - Back Calves and Post Workout Meal'),
('volume-per-muscle', 'deprioritizes already-developed muscle groups during a bulk to correct proportion', 'Sam Sulek temporarily drops back training entirely and reduces shoulder work to about 2-3 moderate sets on occasion because those are already his most-developed areas, deliberately redirecting bulk-phase growth toward lagging body parts (arms, chest, legs) to build a more proportional physique.', 'practice', 'weak', NULL, '{"shoulder_maintenance_sets_low": 2, "shoulder_maintenance_sets_high": 3, "note": "done only occasionally, not every session"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 34 - Forearms and Shoulders - Control Your Thoughts'),
('strength-accessories', 'direct forearm isolation work needed beyond grip-intensive back training', 'Sam Sulek says no strapless, grip-intensive back session has ever fatigued his forearms close to what 4 sets of dedicated forearm curls produce, and argues against the common claim that training back without straps is sufficient forearm work — forearms need direct, dedicated training like any other muscle if size is the goal.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 34 - Forearms and Shoulders - Control Your Thoughts'),
('strength-accessories', 'trains forearm extensors before flexors within a session', 'In a dedicated forearm session, Sam Sulek does reverse-curl/extensor work first while fresh, then moves to heavier flexor/grip curl work afterward, reasoning that the extensor ("back of forearm") mass needs direct building too for a fuller, more balanced look, not just the flexor/grip side.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 34 - Forearms and Shoulders - Control Your Thoughts'),
('equipment', 'reverse pec-deck avoided for rear delts due to shoulder strain; face pulls or bent-over DB laterals substituted', 'Sam Sulek reports the reverse pec-deck machine repeatedly aggravated his shoulder/collarbone, so he now defaults to heavy face pulls or bent-over dumbbell lateral raises for rear delts instead — framing it as an equipment/setup problem for some lifters rather than a reason to skip rear delt training.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 34 - Forearms and Shoulders - Control Your Thoughts'),
('strength-accessories', 'seated incline single-arm lateral raise keeps constant tension through the range', 'Sam Sulek sets an adjustable bench to roughly 70 degrees and leans into it to perform single-arm lateral raises, because that position keeps tension on the side delt through the whole range of motion, unlike a standing lateral raise which loses tension near the bottom of the rep.', 'practice', 'weak', NULL, '{"bench_angle_degrees": 70}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 34 - Forearms and Shoulders - Control Your Thoughts'),
('volume-per-muscle', 'very low weekly set count maintains an already well-developed muscle', 'For a shoulder group Sam Sulek considers already well-developed, a full "shoulder day" is only about 4-5 sets of lateral raises plus roughly 2 sets of rear-delt work, done just occasionally (about once every couple of months), described explicitly as low-stakes maintenance rather than growth-focused volume.', 'practice', 'weak', NULL, '{"lateral_raise_sets": "4-5", "rear_delt_sets": 2, "frequency": "about once every 2 months"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 34 - Forearms and Shoulders - Control Your Thoughts'),
('strength-accessories', 'different load strategy for different forearm sub-regions in the same session', 'Sam Sulek trains the forearm extensor/reverse-curl portion light on purpose, chasing a burning fatigue rather than a strength stimulus, but trains the flexor/grip portion heavy, loading to only about 10-12 reps, reasoning that forearm/grip muscle is inherently very strong (comparable to what an untrained lifter can already grip through a heavy deadlift) and needs real mechanical tension to grow.', 'practice', 'weak', NULL, '{"extensor_sets": "5-6", "flexor_reps_target": "10-12", "note": "extensor sets deliberately light, aimed at burn/fatigue rather than near-max load"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 59 - Calves and Forearms - Tripod in the Gym, Yay or Nay'),
('strength-accessories', 'reduces load set-to-set to keep hitting a target rep window as fatigue builds', 'Within a forearm session, Sam Sulek deliberately drops the dumbbell weight from set to set (e.g., from 20s down to 15s) as local fatigue accumulates, rather than holding load fixed and letting rep count fall, so each set lands in roughly the same target rep range.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 59 - Calves and Forearms - Tripod in the Gym, Yay or Nay'),
('strength-accessories', 'wrist-path cue for grip-curl peak contraction', 'On single-arm cable curls for the forearm flexors, Sam Sulek cues an inward rotational pull — bringing the pinky side of the hand toward the elbow rather than a straight vertical curl — saying this produces a fuller contraction at the bottom, comparable to the squeeze he feels doing a single-arm lat pulldown.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 59 - Calves and Forearms - Tripod in the Gym, Yay or Nay'),
('tempo', 'mixes rep tempo within a single calf session', 'Sam Sulek performs an initial block of calf-raise sets with slow, controlled reps, then deliberately switches to a faster, "bouncier" rep style later in the same session because he finds it drives a bigger pump — while acknowledging that bouncing can also be used to just move more weight without properly working the muscle if done carelessly.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 59 - Calves and Forearms - Tripod in the Gym, Yay or Nay'),
('strength-accessories', 'finishes calves with a pre-fatigue set plus a single-leg bodyweight burnout', 'Sam Sulek closes a calf session with a two-part finisher: a normal double-leg calf-raise set to pre-fatigue, immediately followed by single-leg bodyweight calf raises (using a light hand-assist from the seat) taken to full exhaustion on each leg.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 59 - Calves and Forearms - Tripod in the Gym, Yay or Nay'),
('periodization', 'contradiction: near-daily training, rest driven by systemic fatigue rather than a fixed weekly schedule', 'Sam Sulek distinguishes local muscle soreness from whole-body systemic fatigue, saying a small-muscle-group day (forearms plus calves, or arms alone) doesn''t warrant a rest day afterward because it doesn''t tax the whole system, while a demanding full leg day (hamstring curls, RDLs, squats, leg press, leg extensions, adductors) might; he self-reports roughly one rest day per month during his first three years of training, and sequences a heavy leg day directly into an arm day with no rest between. This runs well below the at-least-1-2-full-rest-days-per-week guidance the corpus generally supports.', 'practice', 'weak', NULL, '{"self_reported_rest_days_per_month_early_years": 1}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 59 - Calves and Forearms - Tripod in the Gym, Yay or Nay'),
('guideline', 'caution against copying an elite lifter''s exact program for their standout body part', 'Sam Sulek argues a lifter with one exceptional body part (using his own arms as the example) doesn''t necessarily have a superior training method for it — they may simply have favorable genetics or muscle insertions — so their specific approach for that muscle shouldn''t be copied wholesale; he advises judging training advice case-by-case against your own response rather than assuming an elite''s routine is optimal for everyone.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 59 - Calves and Forearms - Tripod in the Gym, Yay or Nay'),
('guideline', 'beginner priority is training frequency and consistency over program optimization', 'Sam Sulek argues that for a new lifter, the two most important levers for long-term progress are being genuinely excited to train and showing up consistently — citing training roughly five times a week minimum as a baseline — and that exact exercise/program choices matter far less early on because "the answers reveal themselves" with time in the gym.', 'opinion', 'weak', NULL, '{"beginner_min_sessions_per_week": 5}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 59 - Calves and Forearms - Tripod in the Gym, Yay or Nay'),
('tempo', 'tricep pushdown stretch-squeeze emphasis', 'Shifted tricep pushdown technique (especially on the rope attachment) toward maximizing range of motion — a full stretch through the long head at the top, then a hard peak squeeze at the bottom — and describes this as a recent change from previously just grinding out reps without emphasizing the stretch; feels it is translating to better tricep results.', 'practice', 'weak', NULL, '{"note": "rope pushdown taken to deepest stretch position vs a straight bar; framed as a recent technique change"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 91 - Arms - Comment QnA Questions for Tomorrow'),
('strength-accessories', 'cable curl on incline bench anchored at the feet for a deep stretch', 'Does cable curls seated on an incline bench with the cables run around his feet (instead of standing dumbbell curls), which lets him reach a much deeper stretch position on the biceps; reports a noticeably faster, different rate of fatigue/burn than a regular straight set of dumbbell curls.', 'practice', 'weak', NULL, '{"note": "compared subjectively to a regular straight set of dumbbell curls"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 91 - Arms - Comment QnA Questions for Tomorrow'),
('strength-accessories', 'bicep exercise variety to combat staleness', 'When arm days start to feel stale, deliberately varies bicep exercise selection and angle (regular dumbbell curl, spider curl, bent-over curl, wide cable curl, etc.) — reasoning there are only so many distinct angles to hit the bicep, but each variation produces a different feel and keeps training productive.', 'practice', 'moderate', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 91 - Arms - Comment QnA Questions for Tomorrow'),
('strength-accessories', 'end-of-set decision to add a drop set or superset based on feel', 'On the last set of a movement, doesn''t pre-plan an intensifier — finishes the first portion of the set, then decides in the moment whether to add a drop set or superset based on how much is left in the tank, reasoning that as the final set of an exercise there''s no need to hold anything back.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 91 - Arms - Comment QnA Questions for Tomorrow'),
('strength-accessories', 'rest-pause technique on isolation sets', 'Uses a short (~15 second) rest-pause break to extend a cable curl set past initial failure, reporting several more reps after the brief pause rather than ending the set at the first failure point.', 'practice', 'weak', NULL, '{"rest_pause_seconds": 15, "note": "reported ~3 additional reps after a 15-second pause on a cable curl set"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 91 - Arms - Comment QnA Questions for Tomorrow'),
('periodization', 'alternating emphasis between leg days within a training block', 'Structures leg training as an alternating pair of sessions: one leg day built around heavy pressing (squat pattern) at moderate volume, the next leg day built around heavy RDLs for hamstrings plus more squeeze-focused, higher-rep quad isolation work (e.g. leg extensions with drop sets/supersets) rather than heavy compound lifting.', 'practice', 'weak', NULL, '{"note": "two-leg-day rotation: heavy-press day vs RDL + isolation-squeeze day"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 91 - Arms - Comment QnA Questions for Tomorrow'),
('tempo', 'choosing a sub-maximal load to enable controlled tempo on curls', 'For dumbbell curls, intentionally picks a moderate rather than maximal weight so reps can be done with a brief pause at the top and a slow eccentric while keeping shoulders still; notes a practical floor exists — going too light causes the set to end from burning/mental fatigue before true mechanical (strength) failure is reached.', 'practice', 'weak', NULL, '{"note": "slow eccentric with a brief top-of-rep pause; avoids loads so light that burn ends the set before strength failure does"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 91 - Arms - Comment QnA Questions for Tomorrow'),
('volume', 'contradiction: importance of program details (sets/rest/frequency) vs the basics', 'Argues that granular program variables — exact set counts, whether to insert a rest day, one vs two minutes of rest — explain only a small slice of total hypertrophy outcome (rates it around 10%) compared to genetics, years of consistently training hard, and eating enough; calls program-detail optimization "the icing on the cake." This runs counter to volume/frequency dose-response evidence generally held at higher confidence, where set volume and training frequency have a measurable, non-trivial effect on hypertrophy — flagged here as a gap between an elite practitioner''s lived framing and the literature''s emphasis on program variables.', 'opinion', 'weak', NULL, '{"note": "estimates roughly 80-90% of muscle-building outcome from genetics + consistent hard training + adequate eating combined, with program-detail optimization as a minor remainder"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — They Don''t Know How To Build Muscle'),
('guideline', 'years of hard, consistent training outweighs optimized-but-low-effort training', 'Claims someone who trains hard (close to failure) for years with imperfect technique will build more muscle than someone with textbook-perfect form and diet who consistently stops sets well short of failure — framing effort/proximity-to-failure and long-term consistency as more important than technical polish.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — They Don''t Know How To Build Muscle'),
('periodization', '4-day split cycling with a rest day, structuring a new hypertrophy phase', 'Describes an upcoming hypertrophy-focused training block structured as chest+back day / arms+shoulders day / quad day / hamstring day, run on a "two on, one off" cadence (upper, lower, rest, upper, lower), explicitly begun only after finishing a preceding lower-intensity shoulder-rehab phase.', 'practice', 'weak', NULL, '{"split": "chest+back day, arms+shoulders day, quad day, hamstring day", "cadence": "2 on / 1 off (upper, lower, rest, upper, lower)"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — UPPER BODY TRAINING | HOW TO GROW'),
('volume-per-muscle', 'quads and hamstrings trained as separate dedicated days', 'Splits quad-focused and hamstring-focused leg training into two separate sessions rather than one combined leg day, as part of his standard hypertrophy split.', 'practice', 'weak', NULL, NULL, 'Chris Bumstead (5x Classic Physique Olympia) — UPPER BODY TRAINING | HOW TO GROW'),
('clinical', 'high-rep, low-load rehab work before resuming heavy hypertrophy training', 'During shoulder rehab, trained with isometric split-lunge holds, glute bridges, and rotator cuff work for very high rep counts (sets of 30 reps, six sets) before transitioning back to standard heavier hypertrophy training once the shoulder was judged recovered enough.', 'practice', 'weak', NULL, '{"reps_per_set": 30, "sets": 6, "exercises": "isometric split-lunge holds, glute bridges, rotator cuff work"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — UPPER BODY TRAINING | HOW TO GROW'),
('tempo', '3-1-1-1 tempo on dumbbell press to protect and strengthen the shoulder', 'Used a controlled 3-1-1-1 tempo (controlled lowering, slight pause at the bottom, no momentum) on dumbbell shoulder press while ramping weight back up post-injury, explicitly to protect the shoulder and strengthen it through the lengthened position while controlling the weight through the full range.', 'practice', 'weak', NULL, '{"tempo": "3-1-1-1", "note": "controlled negative, slight pause at bottom, deliberate control through the lengthened position"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — UPPER BODY TRAINING | HOW TO GROW'),
('tempo', 'paused-negative superset finisher for biceps', 'Finishes with a biceps superset done as controlled-negative reps with a 10-second pause held mid-rep, repeated across the set — described as adding meaningful extra fatigue beyond his normal working sets.', 'practice', 'weak', NULL, '{"reps": 10, "pause_seconds": 10, "note": "controlled negative with a mid-rep pause, done as a finishing superset"}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — UPPER BODY TRAINING | HOW TO GROW'),
('progression', 'smaller load jumps preferred with more training experience', 'States that earlier in his career he''d jump weight increments of 10-20 lb at a time without much thought, but now prefers smaller increments (around 5 lb) when progressing load.', 'practice', 'weak', NULL, '{"early_career_increment_lb": [10, 20], "current_preferred_increment_lb": 5}'::jsonb, 'Chris Bumstead (5x Classic Physique Olympia) — UPPER BODY TRAINING | HOW TO GROW'),
('volume', 'reducing set volume during a caloric deficit to manage recovery', 'While cutting, deliberately reduces set volume per exercise (e.g. dropped from 4 sets to 3 on primary lifts) reasoning that less food means less recovery capacity, so matching bulk-phase volume during a deficit is counterproductive; states the priority while cutting is maintaining the strength built during the prior bulk rather than pushing new volume.', 'practice', 'weak', NULL, '{"primary_lift_sets_bulk": 4, "primary_lift_sets_cut": 3, "secondary_sets": "2-3", "isolation_sets": 2, "isolation_reps": 15}'::jsonb, 'Will Tennyson (experiments, self-testing) — How I Transformed My Body in 30 Days'),
('volume-per-muscle', 'primary/secondary/tertiary exercise-order structure with declining sets', 'Organizes each session into primary movements (compound lifts done first, lowest set count), secondary movements (3 sets of 10-12 reps), then tertiary/isolation finishers done last (e.g. 2 sets of 15 reps).', 'practice', 'weak', NULL, '{"secondary_sets": 3, "secondary_reps": "10-12", "tertiary_sets": 2, "tertiary_reps": 15}'::jsonb, 'Will Tennyson (experiments, self-testing) — How I Transformed My Body in 30 Days'),
('volume-per-muscle', 'training each muscle group twice weekly with alternating volume emphasis', 'Trains every muscle group twice per week and balances weekly antagonist-pair volume by shifting one exercise between sessions — e.g. on a combined chest/back/bicep day where chest gets 3 exercises and back gets 2, the second weekly chest/back/bicep day of that week flips to 3 back exercises and 2 chest exercises.', 'practice', 'weak', NULL, '{"frequency_per_muscle_per_week": 2, "day1_chest_exercises": 3, "day1_back_exercises": 2, "day2_chest_exercises": 2, "day2_back_exercises": 3}'::jsonb, 'Will Tennyson (experiments, self-testing) — How I Transformed My Body in 30 Days'),
('progression', 'double progression: rep cap before adding load', 'Uses a double-progression scheme: works a weight within a rep range, and once a top rep threshold (12 reps) is reached, adds a small load increment (5 lb) and repeats the process at the new load.', 'practice', 'weak', NULL, '{"rep_threshold": 12, "load_increment_lb": 5}'::jsonb, 'Will Tennyson (experiments, self-testing) — How I Transformed My Body in 30 Days'),
('strength-accessories', 'reserved free-choice exercise slot for variety', 'Deliberately leaves the last exercise slot of a muscle group''s session open to a free choice (e.g. incline dumbbell curl) rather than fully scripting it, believing built-in variety within an otherwise programmed routine prevents boredom and staleness. Converges independently with Sam Sulek''s stated view that exercise variety keeps training from going stale.', 'practice', 'moderate', NULL, NULL, 'Will Tennyson (experiments, self-testing) — How I Transformed My Body in 30 Days'),
('strength-accessories', 'matching forearm exercise selection to three functional regions', 'Divides forearm training across three functional areas he trains for hypertrophy — the flexor mass (squeezing/gripping), the extensor/backside (opening the hand, wrist extension), and the top portion tied into elbow flexion (worked via hammer-style curls) — and selects exercises (reverse dumbbell wrist curls, cable/barbell wrist curls, hammer curls) to target each region separately.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 64 - Forearms and Calves - Who''s This Workout For'),
('strength-accessories', 'strict light-load isolation for reverse wrist curls', 'Deliberately uses light dumbbells for reverse wrist curls (suggests beginners start as light as 10 lb) and keeps the load light enough that no other muscle (e.g. shoulder) is needed to hold position, prioritizing strict forearm isolation over load; settled on around 7 reps per set as producing the best result for him recently.', 'practice', 'weak', NULL, '{"beginner_starting_weight_lb": 10, "own_working_weight_lb": 20, "reps_per_set": 7}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 64 - Forearms and Calves - Who''s This Workout For'),
('tempo', 'matching partial-rep failure technique to an exercise''s strength curve', 'On dumbbell reverse wrist curls (hardest at the bottom of the rep, near-max tension at full stretch), stops the set at a hard, complete failure point. On barbell wrist curls held behind the back (hardest near full contraction), continues doing partial-range reps past full-range-of-motion failure — contracting as hard as possible through a shrinking range — until even partial reps stop moving, treating this as a valid way to extend a set once the exercise''s resistance profile allows it.', 'practice', 'weak', NULL, '{"working_weight_lb": 80, "rep_range": "15-20"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 64 - Forearms and Calves - Who''s This Workout For'),
('tempo', 'contradiction: momentum-assisted bouncing reps for calf training vs strict controlled tempo', 'Deliberately performs heavy calf raises with visible bouncing/momentum on some sets (loaded to roughly 100+ lb per leg), explicitly acknowledging this isn''t strict/"conventional" form, but defends it because of the fatigue and pump he feels; alternates these bouncing heavy sets with separate slow, fully controlled single-leg calf raise sets in the same session. This directly conflicts with stricter-form guidance — generally held at higher confidence — that full control through the range of motion is preferable for maximizing hypertrophic stimulus and minimizing injury risk; flagged as an elite practitioner knowingly training outside that guidance and reporting that it works for him.', 'practice', 'weak', NULL, '{"note": "heavy bouncing calf-raise sets alternated with slow, controlled single-leg sets in the same session"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 64 - Forearms and Calves - Who''s This Workout For'),
('equipment', 'minimal home-gym equipment sufficient for a full arm session', 'States that with just two pairs of dumbbells (e.g. 50s and 25s) he could put together a solid full arm workout — multiple bicep curl variations (double-arm, single-arm, slow, bent-over/concentration, wide-arm) and several tricep options (kickbacks, overhead extension, skull crushers on the ground) — while acknowledging it wouldn''t be an ideal permanent setup.', 'opinion', 'weak', NULL, '{"dumbbell_pairs": 2, "example_loads_lb": [50, 25]}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 64 - Forearms and Calves - Who''s This Workout For'),
('strength-accessories', 'dedicated direct forearm training vs incidental grip work from back day', 'Trains forearms directly on a dedicated day/movement rather than relying on incidental grip work from back exercises, arguing direct forearm work has practical carryover — added wrist/grip stability improves control and safety on heavy dumbbell/barbell pressing — beyond just aesthetic size; says he has trained forearms this way consistently since early in his lifting career, before he had much size.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 64 - Forearms and Calves - Who''s This Workout For'),
('clinical', 'tibialis raises included for shin/knee-adjacent health', 'Includes tibialis anterior raises (leaning against a wall, feet roughly a foot in front, raising the toes off the ground for 10-15+ reps) in his training, citing physical-therapy-oriented sources that link tibialis strengthening to knee health.', 'practice', 'weak', NULL, '{"reps": "10-15+", "setup": "leaning against a wall, feet ~1 foot in front, raise toes off the ground"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 64 - Forearms and Calves - Who''s This Workout For'),
('volume-per-muscle', 'leg-day split: quads vs hamstrings/calves/adductors', 'Sam Sulek splits leg training into a dedicated quad day and a separate hamstring/calf/adductor day, treating hamstrings, calves, and adductors as a commonly neglected “trifecta” that many lifters skip or undertrain even after a year or more of training.', 'practice', 'weak', NULL, '{"note": "two separate leg days per split: quads-only, then hamstrings+calves+adductors"}'::jsonb, 'Sam Sulek (high-volume physique training) — Offseason Day 23 - Hamstrings Adductors and Calves'),
('strength-accessories', 'adductor (hip adduction) machine as squat stabilizer work', 'He uses the hip adduction machine as a warmup before legs or as a finisher, not primarily for size, because well-developed adductors stabilize against side-to-side motion during free-bar barbell squats — which he considers more dangerous than a forward/backward miss since safety bars do not catch lateral instability.', 'practice', 'weak', NULL, '{"reps": "7-8, heavyish, not to failure", "note": "used as warmup or finisher before/after legs"}'::jsonb, 'Sam Sulek (high-volume physique training) — Offseason Day 23 - Hamstrings Adductors and Calves'),
('tempo', 'hamstring curl execution cue', 'On hamstring curls he uses a deliberate slow-squeeze, slow-stretch, hold-at-the-squeeze tempo, and consciously keeps tension isolated to the hamstring, avoiding using momentum from the lower back or glutes (what he calls “punching” the lower back on each rep), which he believes both wastes hamstring stimulus and creates an unwanted lower-back pump.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Offseason Day 23 - Hamstrings Adductors and Calves'),
('volume-per-muscle', 'adductor set/rep volume', 'His typical adductor session is about 7-8 sets in the 10-20 rep range on the hip adduction machine, using a moderate, not heavy, load, with fatigue building through the set rather than from the load itself.', 'practice', 'weak', NULL, '{"sets": "7-8", "reps": "10-20", "note": "moderate load, not heavy"}'::jsonb, 'Sam Sulek (high-volume physique training) — Offseason Day 23 - Hamstrings Adductors and Calves'),
('strength-accessories', 'seated calf raise retained despite stretch-position critique', 'Despite acknowledging an argument that the seated calf raise does not train the calf in its most lengthened position because the knee-flexed posture shortens the gastrocnemius, he keeps the seated calf raise in his routine because he still gets a strong calf pump from it; he does it single-leg, moderate load, squeeze-focused rather than heavy.', 'opinion', 'weak', NULL, '{"sets": "6-7", "load_lbs": 100, "note": "single-leg, squeeze-focused rather than maximal load"}'::jsonb, 'Sam Sulek (high-volume physique training) — Offseason Day 23 - Hamstrings Adductors and Calves'),
('strength-accessories', 'forearm work sequenced away from heavy dumbbell pressing days', 'He avoids training forearms on the same session as heavy dumbbell bench pressing, wanting wrist/forearm stability completely fresh so that very heavy dumbbells (150 lb) don''t wobble and risk a dangerous dropped-weight failure during the set.', 'practice', 'weak', NULL, '{"note": "forearm day scheduled apart from heavy dumbbell bench day"}'::jsonb, 'Sam Sulek (high-volume physique training) — Offseason Day 23 - Hamstrings Adductors and Calves'),
('volume-per-muscle', 'asymmetric quad vs hamstring training frequency', 'Because quads take noticeably longer to recover from heavy loading than hamstrings, he plans to train quads heavy only about once per week while hitting hamstrings on both leg days in the weekly loop — one heavy-quad/lighter-hamstring day, and one hamstring-only day trained harder with heavier hip-hinge movements and extra volume.', 'practice', 'weak', NULL, '{"note": "quads roughly once per week heavy; hamstrings trained on both leg days, heavier and higher-volume on the hamstring-only day"}'::jsonb, 'Sam Sulek (high-volume physique training) — Forearms and Shoulders + Mentality Tips'),
('detraining', 'fast neural re-adaptation to heavy loads after a lighter training block', 'He believes strength has a fast-recovering neurological component separate from muscle growth, so after weeks of lighter, squeeze-focused training he expects re-exposure to a previously heavy load (e.g., a 3-plate Smith squat) to feel dramatically easier within a single session, because neural firing/motor-unit recruitment returns quickly once the nervous system is re-exposed to that load.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Forearms and Shoulders + Mentality Tips'),
('strength-accessories', 'no direct front-delt isolation work', 'He does not train front delts directly, relying on pressing movements alone for front-delt stimulus, and says this is common practice among pro bodybuilders he has talked to, because the front delt responds well to indirect pressing volume and reaches a point of being “big enough” without isolation work.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Forearms and Shoulders + Mentality Tips'),
('strength-accessories', 'angled lateral raise for a specific delt weak point', 'He modifies the standard lateral raise into an angled “Y-raise” (raised somewhat in front of the body rather than straight out to the side) to specifically target the seam between the front and side delt, after identifying via mirror self-assessment that his shoulder looked rounded from the rear/side but sloped off in front.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Forearms and Shoulders + Mentality Tips'),
('strength-accessories', 'bent-over rear-delt lateral raise cue', 'For bent-over rear-delt laterals, his cue is to keep the shoulder joint fixed and rotate the arm around it rather than letting the movement drift into a shrug, which shifts work to the traps; if isolating rear delts specifically he recommends a lighter load to keep traps out of it, though he says the movement can otherwise be loaded fairly heavy.', 'practice', 'weak', NULL, '{"load_lbs": 50, "note": "example working weight for bent-over lateral raises"}'::jsonb, 'Sam Sulek (high-volume physique training) — Forearms and Shoulders + Mentality Tips'),
('volume-per-muscle', 'forearm flexor/extensor volume split', 'His forearm session pairs about 8 sets of roughly 15 light-weight reps of reverse curls (extensor, back of forearm) taken to a burn/near-failure, followed by several heavier sets of wrist-curl-style flexor work (front of forearm) taken close to failure — treating flexor and extensor sides as separate movements rather than one combined exercise.', 'practice', 'weak', NULL, '{"extensor_sets": 8, "extensor_reps": 15, "note": "flexor work done heavier and closer to failure, exact set count not stated"}'::jsonb, 'Sam Sulek (high-volume physique training) — Forearms and Shoulders + Mentality Tips'),
('tempo', 'added squeeze/tension cue at peak contraction', 'Across most exercises, he adds a deliberate extra moment of tension/squeeze at the peak-contraction (flexed) portion of every rep — no extra range of motion, just intentional extra effort at that point — and believes this consistently produces a better set, pump, and result than moving through the same range of motion without that focus.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Forearms and Shoulders + Mentality Tips'),
('strength-accessories', 'forearm/wrist strength as an injury-prevention factor', 'He believes strong forearms and wrist stability reduce injury risk in other lifts, specifically citing that a weak grip/wrist can let a heavy dumbbell (e.g., during dumbbell bench) become unstable and drop.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Forearms and Shoulders + Mentality Tips'),
('volume-per-muscle', 'target working-set count per muscle group per session', 'His rough target is about 8 hard working sets per muscle group per session, each pushed to failure or beyond using drop sets, assisted reps, or supersets, alternating heavier sets with lighter “squeezing” sets; reaching full fatigue/pump around that 8-set mark is his session-ending signal for that muscle, not a fixed time or rep target.', 'practice', 'weak', NULL, '{"sets_per_muscle": 8, "note": "each set pushed to failure or beyond; heavy and light-squeeze sets alternated"}'::jsonb, 'Sam Sulek (high-volume physique training) — Offseason Day 3 - Chest - Incline Bench is Back'),
('guideline', 'pump as a byproduct of a good session, not the cause of growth', 'He argues a strong pump does not itself drive muscle growth; rather, a hard, well-executed set taken under good recovery conditions almost always produces a strong pump as a side effect. He names four “pillars” that support a good lift — sleep, hydration, diet/feeding, and mental state — and says that when a pump feels subpar, the more useful diagnosis is to check which of those four was off (e.g., short sleep) rather than assuming the training itself failed.', 'opinion', 'weak', NULL, '{"note": "four self-described pillars of a good lift: sleep, hydration, diet, mental state"}'::jsonb, 'Sam Sulek (high-volume physique training) — Offseason Day 3 - Chest - Incline Bench is Back'),
('progression', '10-rep PR preferred over 1-rep max as a progress benchmark', 'He tracks a “10-rep PR” (heaviest weight for 10 clean reps) rather than a 1-rep max as his preferred measure of progress, arguing a 1RM attempt is too easy to inflate with technique cheats (exaggerated back arch, bouncing out of the hole on squats, wrist wraps, slingshots) while a clean 10-rep set is a more honest reflection of a bodybuilder-style lifter''s advancement.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Offseason Day 3 - Chest - Incline Bench is Back'),
('progression', 'strength and muscle size are correlated but not 1:1', 'He argues that strength and muscle size track together only loosely, not directly — pointing out that top powerlifters are not the biggest or most muscular lifters — and that past a certain point, chasing heavier working-set loads stops tracking with more muscle gained, which is part of why he deliberately caps his own top working weight (e.g., a “3-plate” bench) rather than continually pushing for a heavier single.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Offseason Day 3 - Chest - Incline Bench is Back'),
('strength-accessories', 'elbow flare on heavy pressing causing shoulder injury', 'He attributes a roughly 3-month period of a “crunchy,” painful shoulder to a heavy pressing rep done with poor form (elbows flared out too wide instead of tucked), and now treats conservative, cautious weight selection — especially on a first attempt at a new heavy weight, even under peer pressure to keep up with training partners — as worth backing off from if the weight feels wrong.', 'practice', 'weak', NULL, '{"note": "elbow flare during a heavy press led to roughly 3 months of shoulder pain"}'::jsonb, 'Sam Sulek (high-volume physique training) — Offseason Day 3 - Chest - Incline Bench is Back'),
('progression', 'gradual load progression, avoiding large session-to-session jumps', 'He avoids large jumps in working weight between sessions (e.g., will not move straight from 3 plates to 4 plates on bench the next chest day even after a good PR), preferring working-set loads to rise gradually as he adds muscle mass over the course of a bulking phase.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Offseason Day 3 - Chest - Incline Bench is Back'),
('strength-accessories', 'rotating chest exercise selection instead of a fixed routine', 'Sam Sulek deliberately avoids repeating the exact same chest workout session to session — rotating among incline barbell, Smith machine press, machine press, dumbbells, decline cable flies, cable presses, and single-arm cable work so that "none of my lifts are really exactly the same" — saying he is more concerned with hitting the target muscle from a wide array of stimuli than with locking into a repeatable, identical routine.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 41 - Chest - Intensity Above All + Fish Talk'),
('equipment', 'basic equipment is enough; fancy machines are not required', 'Sam Sulek says an incline Smith machine plus some cables is "more than enough to build a solid chest," calling specialty machines (e.g. a converging incline press or a squeeze-combo fly machine) gimmicky, and argues equipment choice matters far less than training mindset and intensity.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 41 - Chest - Intensity Above All + Fish Talk'),
('tempo', 'slow controlled Smith-machine reps to prioritize form over balance', 'Sam Sulek says he prefers slow, controlled reps on the Smith machine bench press because removing the balance demand of a free bar lets him focus on retracting his shoulder blades and feeling his chest do the work, rather than stabilizing the weight.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 41 - Chest - Intensity Above All + Fish Talk'),
('volume-per-muscle', 'low set count, mixed-loading chest session', 'A full chest session that mixed heavy pressing, moderate pressing, and light squeezing fly work totaled six sets (cable press, Smith bench, decline cable flies), which he considered complete and sufficiently pumping without needing more volume.', 'practice', 'weak', NULL, '{"sets": 6, "note": "mixed heavy/moderate/light loading across cable press, Smith bench, decline cable flies"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 41 - Chest - Intensity Above All + Fish Talk'),
('volume-per-muscle', 'adductor set count with slow, deep-stretch tempo', 'Sam Sulek describes his typical adductor work as roughly eight sets on the adductor machine, done very slow and controlled with a deep stretch at end range.', 'practice', 'weak', NULL, '{"sets": 8, "note": "adductor machine, very slow tempo, deep stretch emphasis"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 41 - Chest - Intensity Above All + Fish Talk'),
('progression', 'contradiction: no log book, intuitive load selection', 'Sam Sulek says he does not keep a log book and instead picks his working weights by feel each session, arguing that once past the beginner stage a bodybuilder''s strength and size gains aren''t linear (they cycle with bulk/cut phases), so tracking progressive overload numerically is less necessary for him than simply making every set as intense as possible. This conflicts with mainstream strength-training evidence, which treats systematically tracked progressive overload as a primary driver of continued hypertrophy and strength gains.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 41 - Chest - Intensity Above All + Fish Talk'),
('strength-accessories', 'forearm extensors trained before flexors', 'Sam Sulek starts forearm day with reverse curls (targeting the extensors on the back of the forearm) before regular curls, reasoning that stronger extensors improve pressing stability by making the bar less likely to slip out of the hand, in addition to the aesthetic goal of thickening the back of the forearm.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 46 - Forearms and Calves - Once You''ve Done It You''ll Get It'),
('volume-per-muscle', 'heavy-first, light-squeeze-second loading structure within a session', 'Within a forearm session, Sam Sulek loads heavy first for tension and stimulus (dumbbell curls pushed near failure, with reps dropping to about eight as his cue to reduce the weight), then switches to lighter, more controlled squeezing cable work once the muscle is already fatigued, treating the two loading styles as complementary rather than picking one over the other.', 'practice', 'weak', NULL, '{"note": "heavy dumbbell curls to about 8 reps as the cue to drop weight, followed by lighter squeeze-focused cable work after fatigue"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 46 - Forearms and Calves - Once You''ve Done It You''ll Get It'),
('strength-accessories', 'unilateral calf work to correct a left-right imbalance', 'Sam Sulek trains calves single-leg rather than bilaterally because doing both calves at once lets his stronger leg take over while the weaker leg "eases back," an imbalance he attributes to differences in knee/shin/ankle angle; training unilaterally lets him match rep counts between sides (stopping the stronger leg at the same rep count the weaker leg reached) to keep growth even.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 46 - Forearms and Calves - Once You''ve Done It You''ll Get It'),
('volume-per-muscle', 'calf set count for a burn/pump-focused session', 'A calf-focused session was roughly seven to eight sets of single-leg calf raises at about two-thirds of the machine''s stack weight, aimed mainly at a strong pump and burn rather than maximal loading.', 'practice', 'weak', NULL, '{"sets": "7-8", "note": "single-leg calf raises, roughly two-thirds of stack weight, pump/burn-focused rather than max effort"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 46 - Forearms and Calves - Once You''ve Done It You''ll Get It'),
('smith', 'Smith machine and leg press favored over free-bar squats for quad training volume', 'Sam Sulek says he has deliberately shifted away from heavy free-barbell back squats toward Smith machine squats, hip press, and leg press because free squats are unstable and fatigue the stabilizing/accessory muscles (lower back, adductors) so much that a second heavy set at the same weight is compromised; the more stabilized machines let him accumulate more direct quad-targeted volume without that limiting fatigue.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 53 - Legs - Demonic Squat'),
('smith', 'free-bar squats load the shins differently than Smith/leg press', 'Sam Sulek attributes a shin splint from a heavy free-barbell squat session to the forward-lean, bar-balancing loading pattern of a free squat (kicking into the floor to stay balanced), noting that Smith machine squats and leg press load straight up-and-down with much less of that torque on the shins.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 53 - Legs - Demonic Squat'),
('strength-accessories', 'leg extensions used as pre-exhaust priming before heavy pressing', 'Sam Sulek uses moderate-weight, single-leg alternating leg extensions (sets of five) both as a genuine working set for quads and deliberately as a pre-exhaust/priming tool right before a heavy compound press; he specifically pre-exhausts with leg extensions before leg press on days the leg press stack isn''t heavy enough on its own to be challenging.', 'practice', 'weak', NULL, '{"reps": 5, "note": "single-leg alternating leg extensions, moderate weight, used to prime quads before heavy pressing"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 53 - Legs - Demonic Squat'),
('equipment', 'leg extension machine fit varies by lifter anthropometry', 'Sam Sulek tried three different leg extension machines in the same gym before finding one that matched his limb length and knee angle well, saying the issue isn''t that a machine is objectively bad but that machine geometry needs to match an individual lifter''s proportions.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 53 - Legs - Demonic Squat'),
('progression', 'grip-strength self-check used to autoregulate same-day intensity', 'Sam Sulek says he squeezes his fist before training as a quick readiness check; if grip strength feels diminished he treats it as a signal of systemic fatigue (from sleep, hydration, or food) and backs off planned max-effort work — for example skipping a heavy unspotted squat attempt — in favor of lighter, more controlled work like leg press or leg extensions.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — The Bulk Day 53 - Legs - Demonic Squat'),
('volume', 'more volume is not automatically better, but a workload threshold is needed', 'Sam Sulek states directly that more training volume is not always better, but that a certain minimum workload has to be reached to stimulate results, framing his own recent shift toward more pressing volume for quads as chasing that threshold rather than maximizing volume for its own sake.', 'opinion', 'weak', NULL, '{"note": "more volume is not automatically better; a workload threshold must be reached to stimulate results"}'::jsonb, 'Sam Sulek (high-volume physique training) — The Bulk Day 53 - Legs - Demonic Squat'),
('progression', 'training intensity backs off noticeably while dieting', 'Sam Sulek says his muscular endurance (ability to repeat heavy sets) drops noticeably while dieting even though his max strength barely changes, and he deliberately shifts to lighter, more "squeezing" pump-style sets rather than forcing the same heavy-set volume he used while bulking; a chest session while cutting dropped to one heavy set plus six or seven lighter squeeze sets, versus repeated heavy sets while bulking.', 'practice', 'weak', NULL, '{"note": "chest session while cutting: 1 heavy set plus 6-7 lighter squeeze sets, versus multiple heavy sets during a bulk"}'::jsonb, 'Sam Sulek (high-volume physique training) — Cutzilla Day 67 - Row Focused Back'),
('tempo', 'opinion: heavier loading is not fully replaced by squeezing lighter weight', 'Sam Sulek pushes back on the idea that consciously squeezing a lighter weight harder fully substitutes for adding load, arguing mechanical tension from actual weight still matters; of the two extremes (all light-squeeze vs. all max-heavy) he says he leans toward the heavier end, while still endorsing lighter squeeze work as legitimate, particularly on lower-recovery days.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Cutzilla Day 67 - Row Focused Back'),
('progression', 'autoregulating down to light pump work instead of skipping a session', 'Sam Sulek says that on a day he feels tender or under-recovered but doesn''t want a full rest day, his approach is to do lighter squeezing "pump work" that still breaks a sweat, rather than either forcing heavy weight or skipping the session entirely.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Cutzilla Day 67 - Row Focused Back'),
('strength-accessories', 'row-angle taxonomy and foot position changing pull target', 'Sam Sulek distinguishes three cable row pulling angles — a flat row pulled directly to the torso at roughly 90 degrees to the spine, a higher "upright" row where the hands come up toward the upper back, and an intermediate pulldown-style row — and changes his foot position (moving closer to the stack) on a cable row to shift the pull angle toward the mid-back.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — Cutzilla Day 67 - Row Focused Back'),
('volume-per-muscle', 'back session set structure across row, pulldown, and combo movements', 'A back session consisted of three sets of a mid-back-focused cable row, two sets of a standard lat pulldown, one set of a combined row/pulldown finisher, plus extra uncounted single-arm pullover sets added purely for additional lat pump.', 'practice', 'weak', NULL, '{"row_sets": 3, "pulldown_sets": 2, "combo_finisher_sets": 1, "note": "plus extra uncounted single-arm pullover sets for lat pump"}'::jsonb, 'Sam Sulek (high-volume physique training) — Cutzilla Day 67 - Row Focused Back'),
('volume-per-muscle', 'training back as two distinct sub-regions rather than one muscle', 'Sam Sulek splits back training into two separately-pumped target zones in a session — mid-back/traps (rows) and lats (pull-downs, pull-overs) — rather than treating back as one homogeneous muscle, reasoning that a big muscle group needs each sub-section to get direct, intentional work the same way he already trains shoulders (front/side/rear delts individually) and arms (biceps and triceps as separate blocks).', 'practice', 'weak', NULL, '{"note": "back day totaled about 10 working sets, split roughly evenly between upper-back/trap-focused rows and lat-focused pull-downs/pull-overs"}'::jsonb, 'Sam Sulek (high-volume physique training) — New Back Training Plan'),
('strength-accessories', 'elbow position and pull line changes row target between traps and lats', 'On cable/machine rows, Sam Sulek biases mid-back and traps by flaring the elbows outward and pulling the handle toward the center of the traps with the scapula pulled back and together; he biases lats on the same movement pattern by pulling the handle toward the stomach/beltline with the scapula pulled down and together, describing the bottom of that pulling action as functionally the same muscle action as a lat pull-down.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — New Back Training Plan'),
('strength-accessories', 'mind-muscle connection as a practiced skill, not just a phrase', 'Sam Sulek treats mind-muscle connection as a trainable skill rather than a cliche: during working sets on chest and back specifically (he says shoulders, biceps, and triceps are easier to feel) he deliberately thinks about the target muscle initiating the pull rather than the hand, using the classic cue of treating the hand as a hook, and says being able to voluntarily flex a muscle at rest (lats, hamstrings, pecs) is a sign of good mind-muscle connection worth practicing outside the gym.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — New Back Training Plan'),
('strength-accessories', 'cueing presses as a pulling action of the target muscle, not a push', 'For chest-focused pressing, Sam Sulek cues himself to relax the triceps and think of the chest pulling the arm across the torso rather than pushing the bar with the hands, generalizing this to a pulling-only mental model for resistance training (e.g., cueing a squat/leg extension as the quad pulling the kneecap up rather than the leg pushing the floor away) as a way to keep tension on the intended muscle.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — New Back Training Plan'),
('volume-per-muscle', 'using a full pump as the in-session signal that a muscle has had enough direct volume', 'Sam Sulek decides sets on the fly rather than following a fixed pre-planned set count, using achieving a complete pump in each targeted sub-region (e.g., checking whether lats specifically feel fully pumped before moving to the next section) as his practical stopping signal for how much direct volume a muscle group needs in that session.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — New Back Training Plan'),
('volume-per-muscle', 'shifting quad training toward pressing movements and away from leg extensions', 'Sam Sulek shifted his offseason quad training from roughly 75% leg-extension volume and 20% pressing volume to the reverse — about 70-80% pressing (barbell squat, Smith squat, hack squat, pendulum squat) and around 20% leg extension used mainly as a knee/quad warm-up and as a finisher after pressing — after concluding his previous leg-extension-heavy approach, despite feeling harder and giving a bigger pump, was leaving quad growth on the table.', 'practice', 'weak', NULL, '{"before_leg_extension_pct": 75, "before_pressing_pct": 20, "after_pressing_pct": "70-80", "after_leg_extension_pct": 20}'::jsonb, 'Sam Sulek (high-volume physique training) — 1 Hour QNA - How To Grow Legs and My Favorite Digimon'),
('strength-accessories', 'one heavy near-failure squat set for strength carryover, not for volume', 'Sam Sulek does not use barbell squats to accumulate quad volume, citing the systemic fatigue cost (glutes, lower back, bracing, injury risk from a heavy loaded bar), but keeps one heavy set taken near failure at the start of a quad day because he finds squat strength specifically carries over to every other quad exercise, whereas high volume on leg press does not reliably raise his squat.', 'opinion', 'weak', NULL, '{"note": "one working set of heavy squats near failure at the start of the session, then moves to isolation/machine work for the rest of quad volume"}'::jsonb, 'Sam Sulek (high-volume physique training) — 1 Hour QNA - How To Grow Legs and My Favorite Digimon'),
('periodization', 'training-to-failure effort deliberately reduced during a cutting phase', 'Sam Sulek trains with forced reps and all-out effort during offseason/bulking, but deliberately backs off from maximal effort while dieting, reasoning that the lower-intensity period lets joints (specifically his knees) recover from accumulated heavy loading before he returns to heavy squatting the next offseason — framing reduced training intensity during a cut as a planned recovery window rather than a compromise.', 'practice', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — 1 Hour QNA - How To Grow Legs and My Favorite Digimon'),
('volume-per-muscle', 'settling on under-twice-weekly frequency after years testing higher-frequency extremes', 'After roughly 7-8 years lifting, including phases at 50 total sets per muscle group per week split evenly across two weekly sessions, and a two-a-day split hitting every muscle roughly every 48 hours to chase a hypothesized 48-hour muscle-protein-synthesis window, Sam Sulek''s current routine trains each muscle group a little under twice per week with few rest days, and he reports this has produced steady progress without needing to overthink further changes.', 'practice', 'weak', NULL, '{"historical_extreme_sets_per_muscle_per_week": 50, "current_frequency_per_muscle_per_week": "<2"}'::jsonb, 'Sam Sulek (high-volume physique training) — 1 Hour QNA - How To Grow Legs and My Favorite Digimon'),
('olympic', 'no place for Olympic lifts in bodybuilding-focused training', 'Sam Sulek never performs Olympic lifts such as the clean and jerk, viewing them as worthwhile only if the specific goal is Olympic-lift performance or CrossFit-style training; for a physique/bodybuilding goal he considers dedicated single-joint-focused or hinge lifts (e.g., shoulder press, hip-hinge deadlift variants) more directly useful than cleans.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — 1 Hour QNA - How To Grow Legs and My Favorite Digimon'),
('progression', 'committing to a routine for several weeks before judging or changing it', 'Sam Sulek''s stated practice for evaluating a training approach is to commit to it for multiple weeks before judging whether it worked, reasoning that a routine change takes a few weeks to show up as results; he describes switching plans too quickly (chasing a new split every week, or comparing multiple named approaches without running any of them) as analysis paralysis that prevents ever finding out if a given approach actually worked.', 'opinion', 'weak', NULL, NULL, 'Sam Sulek (high-volume physique training) — 1 Hour QNA - How To Grow Legs and My Favorite Digimon');
